// 한국사능력검정시험(심화) - 77회 실제 기출 + 시대별 예상문제 (15_한능검1급마스터 데이터, 엔진 형식으로 변환 · HAE)
window.QDATA=[{"id":"kh-q001","set":"선사 시대","n":1,"s":1,"q":"[자료] 이 시대 사람들은 동굴이나 막집에 살며 무리를 지어 이동 생활을 하였다. 주먹도끼와 찍개 등 뗀석기를 사용하여 사냥과 채집을 하였다.\n\n밑줄 그은 '이 시대'의 생활 모습으로 옳은 것은?","o":["빗살무늬 토기에 식량을 저장하였다.","가락바퀴를 이용하여 실을 뽑았다.","계급이 발생하여 군장이 등장하였다.","주로 동굴이나 막집에서 이동 생활을 하였다.","반달 돌칼로 벼를 수확하였다."],"a":4,"e":"제시문은 뗀석기·이동 생활을 특징으로 하는 구석기 시대이다. 동굴·막집 생활이 대표적 모습이다. 빗살무늬 토기·가락바퀴는 신석기, 계급·군장·반달 돌칼은 청동기이다.","sec":0},{"id":"kh-q002","set":"선사 시대","n":2,"s":1,"q":"[자료] 서울 암사동 유적에서는 이 토기와 함께 갈돌·갈판이 출토되었다. 사람들은 강가에 움집을 짓고 조·피 등을 재배하기 시작하였다.\n\n밑줄 그은 시대에 대한 설명으로 옳은 것은?","o":["철제 농기구를 사용하였다.","농경과 목축이 시작되었다.","비파형 동검을 제작하였다.","명도전으로 중국과 교역하였다.","고인돌을 만들어 지배자를 매장하였다."],"a":2,"e":"암사동·빗살무늬 토기·움집·조/피 재배는 신석기 시대의 특징이다. 신석기 혁명으로 농경과 목축이 시작되었다. 철제 농기구·명도전은 철기, 비파형 동검·고인돌은 청동기이다.","sec":0},{"id":"kh-q003","set":"선사 시대","n":3,"s":1,"q":"다음 유물이 처음 사용된 시대의 사회 모습으로 옳은 것은? (반달 돌칼, 비파형 동검, 민무늬 토기)","o":["뼈바늘로 옷을 지어 입었다.","계급이 발생하고 군장이 등장하였다.","무리를 지어 이동 생활을 하였다.","우경이 널리 보급되었다.","독서삼품과로 관리를 선발하였다."],"a":2,"e":"반달 돌칼·비파형 동검·민무늬 토기는 청동기 시대 유물이다. 잉여 생산물이 생기면서 계급이 발생하고 군장(족장)이 등장하였다.","sec":0},{"id":"kh-q004","set":"선사 시대","n":4,"s":1,"q":"[자료] 연천 전곡리에서 발견된 이 유물은 동아시아에도 아슐리안형 뗀석기가 존재했음을 보여 주어 세계 고고학계의 주목을 받았다.\n\n밑줄 그은 유물로 옳은 것은?","o":["주먹도끼","빗살무늬 토기","반달 돌칼","세형 동검","거친무늬 거울"],"a":1,"e":"연천 전곡리는 아슐리안형 주먹도끼(뗀석기)가 출토된 구석기 유적이다.","sec":0},{"id":"kh-q005","set":"고조선과 여러 나라","n":1,"s":1,"q":"[자료] 백성에게 금하는 법 8조가 있었다. 사람을 죽인 자는 즉시 죽이고, 남을 다치게 한 자는 곡식으로 배상하며, 도둑질한 자는 노비로 삼는다.\n\n밑줄 그은 법이 시행된 나라에 대한 설명으로 옳은 것은?","o":["소도라는 신성 지역이 있었다.","단군왕검이 건국하였다고 전한다.","영고라는 제천 행사를 열었다.","서옥제라는 혼인 풍습이 있었다.","읍락 간 경계를 중시한 책화가 있었다."],"a":2,"e":"8조법(범금 8조)은 고조선의 사회상을 보여 준다. 고조선은 단군왕검이 건국하였다고 전한다. 소도는 삼한, 영고는 부여, 서옥제는 고구려, 책화는 동예이다.","sec":1},{"id":"kh-q006","set":"고조선과 여러 나라","n":2,"s":1,"q":"[자료] 이 나라는 12월에 영고라는 제천 행사를 열었으며, 왕 아래 마가·우가·저가·구가의 여러 가(加)들이 사출도를 다스렸다.\n\n밑줄 그은 '이 나라'로 옳은 것은?","o":["부여","옥저","삼한","동예","고구려"],"a":1,"e":"영고·사출도·5부족 연맹은 만주 쑹화강 유역의 부여이다.","sec":1},{"id":"kh-q007","set":"고조선과 여러 나라","n":3,"s":1,"q":"(가), (나) 나라에 대한 설명으로 옳은 것은? (가) 혼인을 약속한 여자아이를 데려와 키운 뒤 며느리로 삼았다. (나) 다른 부족의 경계를 침범하면 소·말로 배상하게 하였다.","o":["(가)-무천이라는 제천 행사를 열었다.","(가)-민며느리제라는 혼인 풍습이 있었다.","(나)-특산물로 단궁·과하마가 없었다.","(나)-읍군·삼로가 다스리지 않았다.","(가)-제사장인 천군이 소도를 다스렸다."],"a":2,"e":"(가)는 민며느리제의 옥저, (나)는 책화의 동예이다. 무천은 동예, 소도·천군은 삼한이다. 옥저의 혼인 풍습이 민며느리제이다.","sec":1},{"id":"kh-q008","set":"고조선과 여러 나라","n":4,"s":1,"q":"[자료] 이 나라에서는 정치적 지배자인 신지·읍차와 별도로 제사장인 천군이 소도라는 신성 지역을 다스렸다. 변한에서는 철이 많이 나 낙랑과 왜에 수출하였다.\n\n밑줄 그은 '이 나라'의 특징으로 옳은 것은?","o":["사출도가 있었다.","제정이 분리되어 있었다.","서옥제 풍습이 있었다.","가족 공동 무덤을 만들었다.","영고라는 제천 행사가 있었다."],"a":2,"e":"신지·읍차(정치)와 천군·소도(제사)가 나뉜 것은 삼한의 제정 분리 특징이다.","sec":1},{"id":"kh-q009","set":"삼국 시대","n":1,"s":1,"q":"[자료] 왕은 불교를 수용하고 태학을 설립하였으며, 율령을 반포하여 국가 체제를 정비하였다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["고구려 소수림왕","백제 근초고왕","신라 지증왕","고구려 광개토 대왕","백제 성왕"],"a":1,"e":"불교 수용·태학 설립·율령 반포는 고구려 소수림왕(4세기)의 체제 정비 정책이다.","sec":2},{"id":"kh-q010","set":"삼국 시대","n":2,"s":1,"q":"[자료] 왕은 남으로 마한을 정복하고 북으로 고구려의 평양성을 공격하여 고국원왕을 전사시켰다. 이 시기 백제는 요서·규슈 지방과 교류하였다.\n\n밑줄 그은 '왕'의 재위 시기 사실로 옳은 것은?","o":["사비로 천도하였다.","22담로에 왕족을 파견하였다.","백제의 전성기를 이루었다.","불교를 처음 수용하였다.","관산성 전투에서 전사하였다."],"a":3,"e":"마한 정복·평양성 공격·요서 진출은 백제 근초고왕(4세기) 전성기의 사실이다. 사비 천도·남부여는 성왕, 22담로는 무령왕이다.","sec":2},{"id":"kh-q011","set":"삼국 시대","n":3,"s":1,"q":"[자료] 이 왕은 신라에 침입한 왜를 격퇴하고 만주 일대를 정복하였으며, '영락'이라는 연호를 사용하였다.\n\n밑줄 그은 '이 왕'과 관련된 문화유산으로 옳은 것은?","o":["충주 고구려비","광개토 대왕릉비","단양 신라 적성비","북한산 순수비","사택지적비"],"a":2,"e":"영락 연호·왜 격퇴·만주 정복은 광개토 대왕이다. 그의 업적은 아들 장수왕이 세운 광개토 대왕릉비에 기록되어 있다. 충주 고구려비도 장수왕 때 세워졌으나 남진 관련이다.","sec":2},{"id":"kh-q012","set":"삼국 시대","n":4,"s":1,"q":"[자료] 왕은 국호를 '신라'로 정하고 '왕'이라는 칭호를 사용하였으며, 이사부를 보내 우산국을 복속시켰다.\n\n밑줄 그은 '왕'의 정책으로 옳은 것은?","o":["화랑도를 국가 조직으로 개편하였다.","불교를 공인하였다.","우경을 장려하였다.","한강 유역을 차지하였다.","김흠돌의 난을 진압하였다."],"a":3,"e":"국호 '신라'·왕 칭호·우산국 정벌은 지증왕이다. 지증왕은 우경을 장려하였다. 불교 공인은 법흥왕, 화랑도 개편·한강 차지는 진흥왕이다.","sec":2},{"id":"kh-q013","set":"삼국 시대","n":5,"s":1,"q":"[자료] 왕은 화랑도를 국가적 조직으로 개편하고, 한강 유역을 모두 차지하였으며, 대가야를 정복하였다. 정복지에 순수비를 세웠다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["신라 법흥왕","신라 진흥왕","신라 내물왕","백제 무령왕","고구려 장수왕"],"a":2,"e":"화랑도 개편·한강 유역 장악·대가야 정복·순수비 건립은 신라 진흥왕(6세기)이다.","sec":2},{"id":"kh-q014","set":"남북국 시대(통일신라·발해)","n":1,"s":1,"q":"[자료] 왕은 김흠돌의 난을 진압한 뒤 9주 5소경을 정비하고 관료전을 지급하였으며 녹읍을 폐지하였다. 또 국학을 세웠다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["신문왕","무열왕","원성왕","성덕왕","진성 여왕"],"a":1,"e":"김흠돌의 난 진압·9주 5소경·관료전 지급·녹읍 폐지·국학 설립은 통일신라 신문왕의 왕권 강화 정책이다.","sec":3},{"id":"kh-q015","set":"남북국 시대(통일신라·발해)","n":2,"s":1,"q":"[자료] 대조영이 동모산에서 건국한 이 나라는 문왕 때 상경으로 천도하였고, 선왕 때 전성기를 이루어 '해동성국'이라 불렸다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["9서당 10정을 두었다.","고구려 계승 의식을 내세웠다.","골품제라는 신분제를 운영하였다.","청해진을 설치하여 해상 무역을 장악하였다.","독서삼품과로 관리를 선발하였다."],"a":2,"e":"대조영·동모산·해동성국은 발해이다. 발해는 일본에 보낸 국서에서 '고려국왕'을 칭하는 등 고구려 계승 의식을 뚜렷이 내세웠다. 나머지는 신라이다.","sec":3},{"id":"kh-q016","set":"남북국 시대(통일신라·발해)","n":3,"s":1,"q":"[자료] 그는 당에서 활약하다 귀국하여 완도에 청해진을 설치하고 해적을 소탕하여 동아시아 해상 무역을 장악하였다.\n\n밑줄 그은 '그'로 옳은 것은?","o":["장보고","최치원","김헌창","궁예","견훤"],"a":1,"e":"청해진 설치·해상 무역 장악은 신라 하대의 장보고이다.","sec":3},{"id":"kh-q017","set":"남북국 시대(통일신라·발해)","n":4,"s":1,"q":"신라 하대의 사회 모습으로 옳지 않은 것은?","o":["진골 귀족 간 왕위 다툼이 극심하였다.","6두품과 호족 세력이 성장하였다.","원종과 애노의 난 등 농민 봉기가 일어났다.","선종과 풍수지리설이 유행하였다.","녹읍을 폐지하고 관료전을 지급하였다."],"a":5,"e":"관료전 지급·녹읍 폐지는 신라 중대(신문왕)의 일이다. 나머지는 모두 신라 하대의 특징이다.","sec":3},{"id":"kh-q018","set":"고려 시대","n":1,"s":1,"q":"[자료] 왕은 노비안검법을 실시하여 호족 세력을 약화시키고, 과거제를 시행하여 인재를 등용하였으며, 백관의 공복을 제정하였다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["태조","광종","성종","공민왕","현종"],"a":2,"e":"노비안검법·과거제 시행·공복 제정·황제 칭호·광덕/준풍 연호는 고려 광종의 왕권 강화 정책이다.","sec":4},{"id":"kh-q019","set":"고려 시대","n":2,"s":1,"q":"[자료] 최승로는 시무 28조를 올려 유교 정치 이념을 강조하였다. 이를 받아들인 왕은 12목에 지방관을 파견하고 2성 6부제를 정비하였다.\n\n밑줄 그은 '왕'의 업적으로 옳은 것은?","o":["국자감을 정비하였다.","전민변정도감을 설치하였다.","훈요 10조를 남겼다.","쌍성총관부를 수복하였다.","별무반을 조직하였다."],"a":1,"e":"시무 28조 수용·12목 지방관 파견·2성 6부는 성종이다. 성종은 국자감을 정비하였다. 훈요 10조는 태조, 전민변정도감·쌍성총관부 수복은 공민왕, 별무반은 예종(윤관)이다.","sec":4},{"id":"kh-q020","set":"고려 시대","n":3,"s":1,"q":"[자료] 그는 거란의 1차 침입 때 소손녕과 담판하여 강동 6주를 획득하였다.\n\n밑줄 그은 '그'로 옳은 것은?","o":["서희","강감찬","윤관","김윤후","최무선"],"a":1,"e":"거란 1차 침입 때 외교 담판으로 강동 6주를 얻은 인물은 서희이다. 귀주 대첩은 강감찬이다.","sec":4},{"id":"kh-q021","set":"고려 시대","n":4,"s":1,"q":"[자료] 이 사건은 서경 천도와 금국 정벌, 칭제 건원을 주장하며 일어났으나 김부식이 이끄는 관군에 의해 진압되었다.\n\n밑줄 그은 '이 사건'으로 옳은 것은?","o":["이자겸의 난","묘청의 서경 천도 운동","무신정변","만적의 난","망이·망소이의 난"],"a":2,"e":"서경 천도·금국 정벌·칭제 건원 주장, 김부식의 진압은 묘청의 서경 천도 운동(1135)이다.","sec":4},{"id":"kh-q022","set":"고려 시대","n":5,"s":1,"q":"[자료] 왕은 정동행성 이문소를 폐지하고 쌍성총관부를 공격하여 철령 이북의 땅을 되찾았으며, 전민변정도감을 설치하여 권문세족을 견제하였다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["공민왕","광종","충선왕","우왕","성종"],"a":1,"e":"반원 자주 정책(정동행성 폐지·쌍성총관부 수복·전민변정도감)은 공민왕이다.","sec":4},{"id":"kh-q023","set":"고려 시대","n":6,"s":1,"q":"고려의 문화유산으로 옳지 않은 것은?","o":["상감 청자","팔만대장경","직지심체요절","초조대장경","무구정광대다라니경"],"a":5,"e":"무구정광대다라니경은 통일신라의 목판 인쇄물(경주 불국사 석가탑 출토)이다. 나머지는 고려의 문화유산이다.","sec":4},{"id":"kh-q024","set":"조선 전기","n":1,"s":1,"q":"[자료] 왕은 집현전을 설치하여 학문을 장려하고, 훈민정음을 창제하였으며, 4군 6진을 개척하고 측우기를 제작하게 하였다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["태종","세종","세조","성종","정조"],"a":2,"e":"집현전·훈민정음·4군 6진·측우기·의정부 서사제는 세종의 업적이다.","sec":5},{"id":"kh-q025","set":"조선 전기","n":2,"s":1,"q":"[자료] 왕은 6조 직계제를 실시하고 사병을 혁파하였으며, 호패법을 시행하여 인구를 파악하였다.\n\n밑줄 그은 '왕'의 업적으로 옳은 것은?","o":["경국대전을 완성하였다.","훈민정음을 반포하였다.","왕권 강화를 위해 6조 직계제를 실시하였다.","탕평비를 세웠다.","규장각을 설치하였다."],"a":3,"e":"사병 혁파·호패법·6조 직계제는 태종의 왕권 강화 정책이다. 경국대전 완성은 성종, 탕평비는 영조, 규장각은 정조이다.","sec":5},{"id":"kh-q026","set":"조선 전기","n":3,"s":1,"q":"[자료] 이 기구는 사헌부·사간원과 함께 3사로 불리며, 왕의 자문에 응하고 경연을 주관하였다.\n\n밑줄 그은 '이 기구'로 옳은 것은?","o":["홍문관","승정원","의금부","비변사","춘추관"],"a":1,"e":"경연 주관·왕의 자문, 사헌부·사간원과 함께 3사를 이룬 기구는 홍문관이다. 승정원은 왕명 출납, 의금부는 국왕 직속 사법 기구이다.","sec":5},{"id":"kh-q027","set":"조선 전기","n":4,"s":1,"q":"[자료] 중종 때 등용된 그는 현량과 실시, 소격서 폐지, 위훈 삭제 등 급진적 개혁을 추진하다가 기묘사화로 제거되었다.\n\n밑줄 그은 '그'로 옳은 것은?","o":["조광조","정도전","이황","이이","김종직"],"a":1,"e":"현량과·소격서 폐지·위훈 삭제, 기묘사화로 화를 입은 인물은 조광조이다.","sec":5},{"id":"kh-q028","set":"조선 전기","n":5,"s":1,"q":"[자료] 이 인물은 임진왜란 때 한산도 대첩 등에서 학익진 전법으로 왜의 수군을 크게 물리쳐 남해의 제해권을 장악하였다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["권율","이순신","곽재우","김시민","신립"],"a":2,"e":"한산도 대첩·학익진·수군은 이순신이다. 권율은 행주 대첩, 김시민은 진주 대첩(육전)이다.","sec":5},{"id":"kh-q029","set":"조선 후기","n":1,"s":1,"q":"[자료] 이 제도는 방납의 폐단을 없애기 위해 공납을 토지 결수에 따라 쌀·베·동전 등으로 납부하게 한 것으로, 공인이 등장하는 계기가 되었다.\n\n밑줄 그은 '이 제도'로 옳은 것은?","o":["대동법","영정법","균역법","호포제","과전법"],"a":1,"e":"방납 폐단 해소·토지 기준 공납·공인 등장은 대동법이다. 영정법은 전세, 균역법은 군역 개편이다.","sec":6},{"id":"kh-q030","set":"조선 후기","n":2,"s":1,"q":"[자료] 왕은 붕당의 폐해를 막고자 탕평책을 실시하고 탕평비를 세웠으며, 균역법을 시행하고 신문고를 부활시켰다.\n\n밑줄 그은 '왕'으로 옳은 것은?","o":["영조","정조","숙종","광해군","인조"],"a":1,"e":"탕평비·균역법·신문고 부활·속대전은 영조의 업적이다.","sec":6},{"id":"kh-q031","set":"조선 후기","n":3,"s":1,"q":"[자료] 왕은 규장각을 설치하고 초계문신제를 시행하였으며, 장용영을 두고 수원 화성을 건설하였다.\n\n밑줄 그은 '왕'의 정책으로 옳은 것은?","o":["대동법을 처음 실시하였다.","신해통공으로 금난전권을 폐지하였다.","훈련도감을 설치하였다.","경국대전을 반포하였다.","탕평비를 건립하였다."],"a":2,"e":"규장각·초계문신·장용영·수원 화성은 정조이다. 정조는 신해통공으로 시전 상인의 금난전권을 폐지하였다. 탕평비는 영조이다.","sec":6},{"id":"kh-q032","set":"조선 후기","n":4,"s":1,"q":"[자료] 그는 거중기를 설계하여 수원 화성 축조에 활용하였고, 『목민심서』·『경세유표』 등을 저술하였다.\n\n밑줄 그은 '그'로 옳은 것은?","o":["정약용","박지원","유형원","홍대용","박제가"],"a":1,"e":"거중기·목민심서·경세유표는 실학자 정약용이다.","sec":6},{"id":"kh-q033","set":"조선 후기","n":5,"s":1,"q":"[자료] 평안도 지역에 대한 차별과 세도 정치의 수탈에 항거하여 몰락 양반이 봉기를 일으켜 청천강 이북을 한때 장악하였다.\n\n밑줄 그은 '봉기'로 옳은 것은?","o":["홍경래의 난","임술 농민 봉기","망이·망소이의 난","동학 농민 운동","이괄의 난"],"a":1,"e":"평안도 차별·몰락 양반(홍경래) 주도·청천강 이북 장악은 홍경래의 난(1811)이다.","sec":6},{"id":"kh-q034","set":"개항기(근대)","n":1,"s":1,"q":"[자료] 그는 왕권 강화를 위해 비변사를 축소하고 경복궁을 중건하였으며, 서원을 정리하고 호포제를 실시하였다. 또 척화비를 세워 통상 수교 거부 의지를 밝혔다.\n\n밑줄 그은 '그'의 정책으로 옳은 것은?","o":["갑오개혁을 추진하였다.","대한제국을 수립하였다.","당백전을 발행하였다.","군국기무처를 설치하였다.","독립협회를 창립하였다."],"a":3,"e":"경복궁 중건·서원 철폐·호포제·척화비는 흥선 대원군이다. 경복궁 중건 재원 마련을 위해 당백전을 발행하였다.","sec":7},{"id":"kh-q035","set":"개항기(근대)","n":2,"s":1,"q":"[자료] 운요호 사건을 계기로 체결된 이 조약은 조선이 외국과 맺은 최초의 근대적 조약이자 불평등 조약으로, 부산 등 3개 항구 개항과 해안 측량권·영사 재판권을 규정하였다.\n\n밑줄 그은 '이 조약'으로 옳은 것은?","o":["강화도 조약","조미 수호 통상 조약","제물포 조약","을사늑약","톈진 조약"],"a":1,"e":"운요호 사건·최초의 근대적 불평등 조약·3개 항구 개항·영사 재판권은 강화도 조약(1876)이다.","sec":7},{"id":"kh-q036","set":"개항기(근대)","n":3,"s":1,"q":"[자료] 급진 개화파는 우정총국 개국 축하연을 이용해 정변을 일으키고 14개조 정강을 발표하였으나, 청군의 개입으로 3일 만에 실패하였다.\n\n밑줄 그은 '정변'으로 옳은 것은?","o":["임오군란","갑신정변","갑오개혁","아관파천","을미사변"],"a":2,"e":"우정총국·14개조 정강·3일 천하는 갑신정변(1884)이다.","sec":7},{"id":"kh-q037","set":"개항기(근대)","n":4,"s":1,"q":"[자료] 동학 농민군은 전주성을 점령한 뒤 정부와 화약을 맺고, 전라도 각지에 자치 기구인 이 기구를 설치하여 폐정 개혁을 추진하였다.\n\n밑줄 그은 '이 기구'로 옳은 것은?","o":["집강소","군국기무처","통리기무아문","교정청","독립협회"],"a":1,"e":"전주 화약 후 동학 농민군이 폐정 개혁을 위해 설치한 자치 기구는 집강소이다.","sec":7},{"id":"kh-q038","set":"개항기(근대)","n":5,"s":1,"q":"[자료] 일제는 이 조약을 강제로 체결하여 대한제국의 외교권을 박탈하고 통감부를 설치하였다. 고종은 이에 항거해 헤이그에 특사를 파견하였다.\n\n밑줄 그은 '이 조약'으로 옳은 것은?","o":["을사늑약","한일 의정서","정미 7조약","기유각서","한일 병합 조약"],"a":1,"e":"외교권 박탈·통감부 설치·헤이그 특사는 을사늑약(1905)이다. 정미 7조약(1907)은 군대 해산을 규정하였다.","sec":7},{"id":"kh-q039","set":"개항기(근대)","n":6,"s":1,"q":"[자료] 이 단체는 독립문을 건립하고 만민 공동회·관민 공동회를 개최하여 자주 국권과 민권 신장을 주장하였다.\n\n밑줄 그은 '이 단체'로 옳은 것은?","o":["독립협회","신민회","보안회","대한 자강회","신간회"],"a":1,"e":"독립문·만민 공동회·관민 공동회는 독립협회(1896)이다.","sec":7},{"id":"kh-q040","set":"일제 강점기","n":1,"s":1,"q":"[자료] 1910년대 일제는 헌병 경찰을 앞세운 무단 통치를 실시하고, 이 사업을 벌여 기한 내에 신고하지 않은 토지를 총독부가 차지하였다.\n\n밑줄 그은 '이 사업'으로 옳은 것은?","o":["토지 조사 사업","산미 증식 계획","회사령","방곡령","농지 개혁"],"a":1,"e":"1910년대 기한부 신고제로 토지를 약탈한 것은 토지 조사 사업이다. 산미 증식 계획은 1920년대이다.","sec":8},{"id":"kh-q041","set":"일제 강점기","n":2,"s":1,"q":"[자료] 1919년 고종의 인산일을 계기로 시작된 이 운동은 전국적·거족적 만세 시위로 확산되었고, 대한민국 임시정부 수립의 계기가 되었다.\n\n밑줄 그은 '이 운동'의 결과로 옳은 것은?","o":["일제가 무단 통치에서 문화 통치로 전환하였다.","조선 총독부가 설치되었다.","회사령이 제정되었다.","을사늑약이 체결되었다.","국채 보상 운동이 시작되었다."],"a":1,"e":"3·1 운동(1919)의 결과 일제는 무단 통치를 이른바 문화 통치로 전환하였고, 임시정부가 수립되었다.","sec":8},{"id":"kh-q042","set":"일제 강점기","n":3,"s":1,"q":"[자료] 홍범도의 대한 독립군 등이 봉오동에서, 이어 김좌진의 북로 군정서 등이 청산리 일대에서 일본군을 크게 격파하였다.\n\n이 전투들이 일어난 시기의 국외 무장 투쟁에 대한 설명으로 옳은 것은?","o":["한국광복군이 대일 선전 포고를 하였다.","1920년 봉오동·청산리에서 큰 승리를 거두었다.","조선 의용대가 중국 관내에서 결성되었다.","한인 애국단이 조직되었다.","자유시 참변 이전 사건이 없었다."],"a":2,"e":"봉오동·청산리 대첩은 1920년의 대표적 무장 독립 전쟁 승리이다. 한국광복군(1940)·조선 의용대(1938)·한인 애국단(1931)은 1930년대 이후이다.","sec":8},{"id":"kh-q043","set":"일제 강점기","n":4,"s":1,"q":"[자료] 이 단체는 1927년 비타협적 민족주의 세력과 사회주의 세력이 연합하여 창립한 국내 최대 규모의 민족 유일당으로, 광주 학생 항일 운동에 조사단을 파견하였다.\n\n밑줄 그은 '이 단체'로 옳은 것은?","o":["신간회","신민회","대한 광복회","조선어학회","대한민국 임시정부"],"a":1,"e":"1927년 민족 유일당·좌우 연합·광주 학생 항일 운동 지원은 신간회이다.","sec":8},{"id":"kh-q044","set":"일제 강점기","n":5,"s":1,"q":"[자료] 김구가 조직한 이 단체 소속의 윤봉길은 상하이 훙커우 공원에서 열린 일왕 생일 기념식에 폭탄을 던졌다.\n\n밑줄 그은 '이 단체'로 옳은 것은?","o":["한인 애국단","의열단","한국광복군","북로 군정서","조선 혁명군"],"a":1,"e":"김구가 조직하고 이봉창·윤봉길이 활동한 단체는 한인 애국단(1931)이다. 의열단은 김원봉이 조직하였다.","sec":8},{"id":"kh-q045","set":"일제 강점기","n":6,"s":1,"q":"[자료] 1930년대 후반 이후 일제는 황국 신민 서사 암송, 신사 참배, 이 정책 등을 강요하여 우리 민족의 정체성을 말살하려 하였다.\n\n밑줄 그은 '이 정책'으로 옳은 것은?","o":["창씨개명","산미 증식 계획","토지 조사 사업","회사령","방곡령"],"a":1,"e":"민족 말살 통치기의 성과 정책으로 신사 참배·황국 신민 서사와 함께 강요된 것은 창씨개명이다.","sec":8},{"id":"kh-q046","set":"현대","n":1,"s":1,"q":"[자료] 1945년 12월 이 회의에서 한반도에 임시 민주 정부 수립과 최고 5년간의 신탁 통치 등이 결정되면서, 국내에서 신탁 통치를 둘러싼 좌우 대립이 격화되었다.\n\n밑줄 그은 '이 회의'로 옳은 것은?","o":["모스크바 3국 외상 회의","카이로 회담","얄타 회담","파리 강화 회의","포츠담 회담"],"a":1,"e":"1945년 12월 임시 정부 수립·신탁 통치·미소 공동 위원회 설치를 결정한 것은 모스크바 3국 외상 회의이다.","sec":9},{"id":"kh-q047","set":"현대","n":2,"s":1,"q":"[자료] 1960년 3·15 부정선거에 항거하여 일어난 이 사건으로 이승만 대통령이 하야하고 자유당 정권이 붕괴되었다.\n\n밑줄 그은 '이 사건'으로 옳은 것은?","o":["4·19 혁명","5·16 군사 정변","6월 민주 항쟁","부마 항쟁","5·18 민주화 운동"],"a":1,"e":"3·15 부정선거·이승만 하야는 4·19 혁명(1960)이다.","sec":9},{"id":"kh-q048","set":"현대","n":3,"s":1,"q":"[자료] 1987년 박종철 고문치사와 4·13 호헌 조치에 반발하여 전개된 이 항쟁의 결과, 여당 대표가 6·29 선언을 발표하여 대통령 직선제 개헌이 이루어졌다.\n\n밑줄 그은 '이 항쟁'으로 옳은 것은?","o":["6월 민주 항쟁","4·19 혁명","5·18 민주화 운동","부마 항쟁","2·28 민주 운동"],"a":1,"e":"박종철·4·13 호헌 철폐·6·29 선언·직선제 개헌은 6월 민주 항쟁(1987)이다.","sec":9},{"id":"kh-q049","set":"현대","n":4,"s":1,"q":"[자료] 이 정변으로 정권을 잡은 세력은 이후 3선 개헌과 유신 헌법을 통해 장기 집권을 도모하였으며, 경제 개발 5개년 계획과 새마을 운동을 추진하였다.\n\n밑줄 그은 '정변'으로 옳은 것은?","o":["5·16 군사 정변","12·12 사태","4·19 혁명","10·26 사태","6·10 만세 운동"],"a":1,"e":"3선 개헌·유신·경제 개발 계획·새마을 운동으로 이어진 것은 5·16 군사 정변(1961, 박정희)이다.","sec":9},{"id":"kh-q050","set":"현대","n":5,"s":1,"q":"6·25 전쟁의 전개 과정을 순서대로 바르게 나열한 것은? (가) 인천 상륙 작전 (나) 북한군 남침 (다) 정전 협정 체결 (라) 중국군 개입","o":["(나)-(가)-(라)-(다)","(나)-(라)-(가)-(다)","(가)-(나)-(라)-(다)","(나)-(가)-(다)-(라)","(라)-(나)-(가)-(다)"],"a":1,"e":"북한군 남침(1950.6) → 인천 상륙 작전(1950.9) → 중국군 개입(1950.10~) → 정전 협정(1953.7) 순이다.","sec":9},{"id":"kh-q101","set":"선사 시대","n":5,"s":1,"q":"[자료] 이 시대 사람들은 강가나 바닷가에 움집을 짓고 정착 생활을 시작하였다. 가락바퀴로 실을 뽑고 뼈바늘로 옷이나 그물을 만들었으며, 조와 피 등을 재배하였다.\n\n밑줄 그은 '이 시대'의 생활 모습으로 옳은 것은?","o":["소도라는 신성 지역이 있었다.","애니미즘 등 원시 신앙이 나타났다.","반달 돌칼로 벼를 수확하였다.","철제 무기를 사용하여 정복 전쟁을 벌였다.","무리를 지어 이동 생활을 하였다."],"a":2,"e":"움집·가락바퀴·뼈바늘·조/피 재배는 신석기 시대이다. 이 시기에는 자연물과 자연 현상에 영혼이 있다고 믿는 애니미즘 등 원시 신앙이 나타났다. 반달 돌칼은 청동기, 철제 무기는 철기, 이동 생활은 구석기이다.","sec":0},{"id":"kh-q102","set":"선사 시대","n":6,"s":1,"q":"[자료] 이 유물은 진흙을 빚어 만든 것으로, 가운데 구멍에 축을 끼워 돌리면서 실을 자아내는 데 사용되었다. 신석기 시대에 옷이나 그물을 만드는 데 쓰였다.\n\n밑줄 그은 '이 유물'로 옳은 것은?","o":["가락바퀴","비파형 동검","반달 돌칼","명도전","거푸집"],"a":1,"e":"실을 뽑는 데 쓰인 신석기 시대 유물은 가락바퀴이다. 비파형 동검·반달 돌칼·거푸집은 청동기, 명도전은 철기 유물이다.","sec":0},{"id":"kh-q103","set":"선사 시대","n":7,"s":1,"q":"다음 유물이 처음 제작된 시대에 대한 설명으로 옳은 것은? (고인돌, 미송리식 토기, 비파형 동검)","o":["철제 농기구로 농사를 지었다.","계급이 발생하고 군장이 등장하였다.","빙하기가 끝나고 농경이 처음 시작되었다.","동굴이나 막집에서 이동 생활을 하였다.","명도전으로 중국과 교역하였다."],"a":2,"e":"고인돌·미송리식 토기·비파형 동검은 청동기 시대 유물이다. 이 시기에 잉여 생산물이 생겨 계급이 발생하고 군장이 등장하였다. 철제 농기구·명도전은 철기, 농경 시작은 신석기, 이동 생활은 구석기이다.","sec":0},{"id":"kh-q104","set":"선사 시대","n":8,"s":1,"q":"[자료] 이 무덤은 거대한 덮개돌을 받침돌 위에 올려 만든 것으로, 많은 노동력이 동원되어야 축조할 수 있었다. 이를 통해 당시 사회에 강력한 지배자가 있었음을 알 수 있다.\n\n밑줄 그은 '이 무덤'이 만들어진 시대의 사회 모습으로 옳은 것은?","o":["우경이 널리 보급되었다.","계급이 없는 평등한 공동체를 이루었다.","거푸집을 이용하여 청동기를 제작하였다.","독서삼품과로 관리를 선발하였다.","빗살무늬 토기에 식량을 저장하였다."],"a":3,"e":"고인돌은 청동기 시대의 지배층 무덤이다. 이 시기에는 거푸집을 이용해 비파형 동검 등 청동기를 직접 제작하였다. 빗살무늬 토기는 신석기, 우경 보급과 독서삼품과는 후대의 사실이다.","sec":0},{"id":"kh-q105","set":"선사 시대","n":9,"s":1,"q":"[자료] 이 유물은 청동 도구를 대량으로 만들기 위해 사용한 틀로, 우리나라에서 청동기를 직접 제작하였음을 보여 준다. 세형 동검 등을 만드는 데 이용되었다.\n\n밑줄 그은 '이 유물'로 옳은 것은?","o":["갈돌과 갈판","슴베찌르개","거푸집","주먹도끼","빗살무늬 토기"],"a":3,"e":"청동기를 만드는 틀은 거푸집이다. 갈돌·갈판·빗살무늬 토기는 신석기, 슴베찌르개·주먹도끼는 구석기 유물이다.","sec":0},{"id":"kh-q106","set":"선사 시대","n":10,"s":1,"q":"[자료] 이 화폐는 칼 모양의 청동 화폐로, 우리나라 여러 유적에서 출토되어 당시 중국(연나라 등)과 활발히 교역하였음을 보여 준다.\n\n밑줄 그은 '이 화폐'가 사용된 시대에 대한 설명으로 옳은 것은?","o":["철기가 널리 보급되었다.","농경과 목축이 처음 시작되었다.","막집에서 이동 생활을 하였다.","빗살무늬 토기를 처음 만들었다.","계급이 없는 평등 사회였다."],"a":1,"e":"명도전은 철기 시대에 중국과 교역하였음을 보여 주는 청동 화폐이다. 이 시기에는 철기가 널리 보급되었다. 농경 시작·빗살무늬 토기는 신석기, 이동 생활은 구석기이다.","sec":0},{"id":"kh-q107","set":"선사 시대","n":11,"s":1,"q":"[자료] 이 유물은 초기 철기 시대에 만들어진 청동검으로, 비파형 동검보다 폭이 좁고 날렵하며 한반도에서 독자적으로 발전한 형태이다.\n\n밑줄 그은 '이 유물'로 옳은 것은?","o":["세형 동검","반달 돌칼","가락바퀴","주먹도끼","갈돌"],"a":1,"e":"비파형 동검이 한반도에서 독자적으로 발전한 형태가 세형 동검(초기 철기)이다. 반달 돌칼은 청동기, 가락바퀴·갈돌은 신석기, 주먹도끼는 구석기 유물이다.","sec":0},{"id":"kh-q108","set":"선사 시대","n":12,"s":1,"q":"[자료] 이 유물은 구석기 시대 후기에 만들어진 것으로, 나무나 뼈 자루에 꽂아 창처럼 사용할 수 있도록 아랫부분에 슴베를 만든 뗀석기이다.\n\n밑줄 그은 '이 유물'을 사용한 시대의 생활 모습으로 옳은 것은?","o":["가락바퀴로 실을 뽑았다.","고인돌을 만들어 지배자를 매장하였다.","주로 사냥과 채집으로 식량을 구하였다.","벼농사를 지어 반달 돌칼로 수확하였다.","철제 갑옷을 만들어 사용하였다."],"a":3,"e":"슴베찌르개는 구석기 후기의 뗀석기이다. 구석기 시대 사람들은 사냥과 채집으로 식량을 구하며 이동 생활을 하였다. 가락바퀴는 신석기, 고인돌·반달 돌칼은 청동기, 철제 갑옷은 철기이다.","sec":0},{"id":"kh-q109","set":"선사 시대","n":13,"s":1,"q":"신석기 시대의 생활 모습으로 옳지 않은 것은?","o":["강가에 움집을 짓고 정착하였다.","갈돌과 갈판으로 곡식을 갈았다.","조·피 등을 재배하기 시작하였다.","가락바퀴로 실을 뽑아 옷을 만들었다.","계급이 발생하여 군장이 등장하였다."],"a":5,"e":"움집 정착, 갈돌·갈판, 조/피 재배, 가락바퀴는 모두 신석기의 특징이다. 계급 발생과 군장 등장은 잉여 생산물이 생긴 청동기 시대의 모습이므로 옳지 않다.","sec":0},{"id":"kh-q110","set":"선사 시대","n":14,"s":1,"q":"[자료] 이 시대의 유적으로는 서울 암사동, 부산 동삼동, 양양 오산리 등이 있다. 사람들은 조개껍데기로 가면을 만들거나 치레걸이(장신구)를 만들기도 하였다.\n\n밑줄 그은 '이 시대'에 대한 설명으로 옳은 것은?","o":["반달 돌칼로 벼를 수확하였다.","빗살무늬 토기를 만들어 식량을 저장하였다.","세형 동검을 제작하였다.","사출도라는 행정 구역이 있었다.","명도전으로 중국과 교역하였다."],"a":2,"e":"암사동·동삼동·오산리는 신석기 유적이다. 신석기 시대에는 빗살무늬 토기를 만들어 식량을 저장·조리하였다. 반달 돌칼은 청동기, 세형 동검·명도전은 철기, 사출도는 부여의 특징이다.","sec":0},{"id":"kh-q111","set":"고조선과 여러 나라","n":5,"s":1,"q":"[자료] 환웅이 무리를 이끌고 태백산 신단수 아래로 내려와 세상을 다스렸고, 이후 곰에서 사람이 된 웅녀와 혼인하여 낳은 아들이 이 나라를 세웠다고 전한다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["영고라는 제천 행사를 열었다.","제정이 분리된 사회였다.","단군왕검이 다스렸다고 전한다.","서옥제라는 혼인 풍습이 있었다.","읍락 간 경계를 중시한 책화가 있었다."],"a":3,"e":"단군 신화는 고조선의 건국 이야기로, 제정일치 사회의 지배자인 단군왕검이 다스렸다고 전한다. 영고는 부여, 서옥제는 고구려, 책화는 동예, 제정 분리는 삼한이다.","sec":1},{"id":"kh-q112","set":"고조선과 여러 나라","n":6,"s":1,"q":"[자료] 진 · 한 교체기에 무리를 이끌고 고조선으로 온 그는 준왕을 몰아내고 왕이 되었다. 이후 고조선은 중국의 철기 문화를 본격적으로 수용하고 중계 무역으로 성장하였다.\n\n밑줄 그은 인물이 집권한 이후 고조선의 사실로 옳은 것은?","o":["8조법이 처음 만들어졌다.","진번·임둔 등을 복속하고 세력을 넓혔다.","단군왕검이 나라를 세웠다.","소도라는 신성 지역을 두었다.","마가·우가 등이 사출도를 다스렸다."],"a":2,"e":"위만은 준왕을 몰아내고 위만 조선을 세웠으며, 진번·임둔 등을 복속하고 중계 무역으로 성장하였다. 단군 건국은 위만 이전, 소도는 삼한, 사출도는 부여이다.","sec":1},{"id":"kh-q113","set":"고조선과 여러 나라","n":7,"s":1,"q":"[자료] 이 나라는 한 무제의 공격을 받아 왕검성이 함락되면서 멸망하였고, 그 자리에는 낙랑 등 네 개의 군현이 설치되었다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["범금 8조로 사회 질서를 유지하였다.","무천이라는 제천 행사를 열었다.","민며느리제라는 혼인 풍습이 있었다.","신지·읍차가 소국을 다스렸다.","가족 공동 무덤을 만들었다."],"a":1,"e":"한 무제에게 멸망하고 한 군현이 설치된 나라는 고조선이다. 고조선은 범금 8조(8조법)로 사회를 유지하였다. 무천은 동예, 민며느리제는 옥저, 신지·읍차는 삼한, 가족 공동 무덤은 옥저이다.","sec":1},{"id":"kh-q114","set":"고조선과 여러 나라","n":8,"s":1,"q":"[자료] 이 나라에서는 왕이 죽으면 많은 사람을 함께 묻는 순장의 풍습이 있었고, 도둑질을 하면 훔친 물건의 12배로 갚게 하는 법이 있었다.\n\n밑줄 그은 '이 나라'로 옳은 것은?","o":["부여","옥저","동예","삼한","고구려"],"a":1,"e":"순장과 1책 12법(도둑질 시 12배 배상)은 만주 쑹화강 유역의 부여의 풍습이다.","sec":1},{"id":"kh-q115","set":"고조선과 여러 나라","n":9,"s":1,"q":"[자료] 이 나라에는 혼인을 하면 남자가 여자 집 뒤에 지은 작은 집(서옥)에서 살다가, 자식이 장성하면 아내를 데리고 자기 집으로 돌아가는 풍습이 있었다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["사출도라는 행정 구역이 있었다.","제가 회의에서 국가의 중대사를 결정하였다.","제사장인 천군이 소도를 다스렸다.","단궁·과하마·반어피가 특산물이었다.","가족이 죽으면 뼈를 한 무덤에 묻었다."],"a":2,"e":"서옥제는 초기 고구려의 혼인 풍습이다. 고구려에서는 제가 회의에서 국가의 중대사를 결정하였다. 사출도는 부여, 소도·천군은 삼한, 단궁·과하마는 동예, 가족 공동 무덤은 옥저이다.","sec":1},{"id":"kh-q116","set":"고조선과 여러 나라","n":10,"s":1,"q":"[자료] 이 나라는 10월에 동맹이라는 제천 행사를 열었다. 왕 아래 상가·고추가 등의 대가들이 각각 관리를 거느렸다.\n\n밑줄 그은 '이 나라'로 옳은 것은?","o":["고구려","부여","옥저","동예","삼한"],"a":1,"e":"10월 동맹과 상가·고추가 등의 대가는 초기 고구려의 특징이다.","sec":1},{"id":"kh-q117","set":"고조선과 여러 나라","n":11,"s":1,"q":"[자료] 이 나라는 매년 10월에 무천이라는 제천 행사를 열었으며, 단궁·과하마·반어피 등이 특산물로 유명하였다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["영고라는 제천 행사를 열었다.","다른 부족의 경계를 침범하면 소·말로 배상하게 하였다.","서옥제라는 혼인 풍습이 있었다.","제정이 분리된 사회였다.","사출도라는 행정 구역이 있었다."],"a":2,"e":"무천·단궁·과하마·반어피는 동예의 특징이다. 동예에는 다른 부족의 경계를 침범하면 노비나 소·말로 배상하는 책화가 있었다. 영고·사출도는 부여, 서옥제는 고구려, 제정 분리는 삼한이다.","sec":1},{"id":"kh-q118","set":"고조선과 여러 나라","n":12,"s":1,"q":"[자료] 이 나라는 소금과 해산물이 풍부하였다. 혼인을 약속한 여자아이를 남자 집에서 데려다 키운 뒤 며느리로 삼는 풍습과, 가족이 죽으면 뼈를 추려 한 무덤에 묻는 풍습이 있었다.\n\n밑줄 그은 '이 나라'로 옳은 것은?","o":["부여","고구려","옥저","삼한","동예"],"a":3,"e":"민며느리제와 가족 공동 무덤(골장제)은 동해안의 옥저의 풍습이다.","sec":1},{"id":"kh-q119","set":"고조선과 여러 나라","n":13,"s":1,"q":"[자료] 이 지역의 여러 소국에서는 5월과 10월에 하늘에 제사를 지내는 계절제를 열었다. 이때 사람들은 무리를 지어 노래하고 춤을 추었다.\n\n밑줄 그은 지역에 대한 설명으로 옳은 것은?","o":["사출도라는 행정 구역이 있었다.","벼농사가 발달하여 저수지를 많이 만들었다.","서옥제라는 혼인 풍습이 있었다.","순장의 풍습이 있었다.","단군왕검이 다스렸다고 전한다."],"a":2,"e":"5월·10월 계절제(수릿날·계절제)를 지낸 곳은 삼한이다. 삼한은 벼농사가 발달하여 김제 벽골제 등 저수지를 많이 만들었다. 사출도·순장은 부여, 서옥제는 고구려, 단군은 고조선이다.","sec":1},{"id":"kh-q120","set":"고조선과 여러 나라","n":14,"s":1,"q":"[자료] 이 지역에서는 철이 많이 생산되어 낙랑과 왜 등에 수출하였으며, 철을 화폐처럼 사용하기도 하였다.\n\n밑줄 그은 지역으로 옳은 것은?","o":["변한","부여","옥저","동예","고구려"],"a":1,"e":"철이 많이 나 낙랑과 왜에 수출하고 화폐처럼 사용한 곳은 삼한 가운데 변한이다. 이 지역은 후에 가야로 발전하였다.","sec":1},{"id":"kh-q121","set":"고조선과 여러 나라","n":15,"s":1,"q":"(가), (나) 나라에 대한 설명으로 옳은 것은? (가) 12월에 영고라는 제천 행사를 열었다. (나) 10월에 동맹이라는 제천 행사를 열었다.","o":["(가)-마가·우가 등이 사출도를 다스렸다.","(가)-민며느리제라는 혼인 풍습이 있었다.","(나)-소도라는 신성 지역을 두었다.","(나)-특산물로 단궁·과하마가 있었다.","(가)-제정이 분리된 사회였다."],"a":1,"e":"(가)는 영고의 부여, (나)는 동맹의 고구려이다. 부여에서는 마가·우가·저가·구가가 사출도를 다스렸다. 민며느리제는 옥저, 소도는 삼한, 단궁·과하마는 동예이다.","sec":1},{"id":"kh-q122","set":"고조선과 여러 나라","n":16,"s":1,"q":"[자료] 이 나라 사람들은 대부분 반지하 형태의 반움집에 살았고, 소국들이 모여 연맹을 이루었다. 정치적 지배자로 신지·읍차 등이 있었다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["영고라는 제천 행사를 열었다.","제사와 정치가 분리되어 있었다.","서옥제라는 혼인 풍습이 있었다.","순장의 풍습이 있었다.","가족 공동 무덤을 만들었다."],"a":2,"e":"신지·읍차가 다스린 소국 연맹은 삼한이다. 삼한은 정치 지배자(신지·읍차)와 제사장(천군)이 나뉜 제정 분리 사회였다. 영고·순장은 부여, 서옥제는 고구려, 가족 공동 무덤은 옥저이다.","sec":1},{"id":"kh-q123","set":"고조선과 여러 나라","n":17,"s":1,"q":"부여에 대한 설명으로 옳은 것은?","o":["민며느리제라는 혼인 풍습이 있었다.","마가·우가 등이 사출도를 다스렸다.","무천이라는 제천 행사를 열었다.","제사장인 천군이 소도를 다스렸다.","서옥제라는 혼인 풍습이 있었다."],"a":2,"e":"부여는 왕 아래 마가·우가·저가·구가가 각각 사출도를 다스린 5부족 연맹체였다. 민며느리제는 옥저, 무천은 동예, 소도·천군은 삼한, 서옥제는 고구려이다.","sec":1},{"id":"kh-q124","set":"고조선과 여러 나라","n":18,"s":1,"q":"여러 나라의 제천 행사를 바르게 연결한 것은?","o":["부여-무천","고구려-영고","동예-동맹","삼한-수릿날 및 계절제","옥저-소도"],"a":4,"e":"삼한은 5월 수릿날과 10월 계절제를 지냈다. 부여는 영고, 고구려는 동맹, 동예는 무천이다. 옥저는 뚜렷한 제천 행사 기록이 없고 소도는 삼한의 신성 지역이다.","sec":1},{"id":"kh-q127","set":"삼국 시대","n":6,"s":1,"q":"[자료] 왕이 명령하기를, 굶주린 백성에게 봄에 곡식을 빌려주었다가 가을에 갚게 하라 하였다. 재상 을파소의 건의로 이 제도가 처음 시행되었다.\n\n밑줄 그은 제도를 시행한 왕의 업적으로 옳은 것은?","o":["진대법을 실시하여 빈민을 구제하였다.","태학을 세워 인재를 양성하였다.","평양으로 수도를 옮겼다.","낙랑군을 몰아내었다.","영락이라는 연호를 사용하였다."],"a":1,"e":"을파소의 건의로 봄에 빌려주고 가을에 갚게 한 제도는 고구려 고국천왕의 진대법이다. 태학은 소수림왕, 평양 천도는 장수왕, 영락 연호는 광개토대왕의 업적이다.","sec":2},{"id":"kh-q128","set":"삼국 시대","n":7,"s":1,"q":"[자료] 이 왕은 지방의 22담로에 왕족을 파견하여 다스리게 하였으며, 중국 남조의 양나라와 교류하였다. 무덤은 벽돌무덤 양식으로 조성되었다.\n\n밑줄 그은 '이 왕'에 대한 설명으로 옳은 것은?","o":["관산성 전투에서 전사하였다.","22담로에 왕족을 보내 지방을 통제하였다.","사비로 천도하고 국호를 남부여로 고쳤다.","한강 유역을 최초로 확보하였다.","고흥에게 서기를 편찬하게 하였다."],"a":2,"e":"22담로에 왕족을 파견하고 양나라와 교류한 인물은 백제 무령왕이다. 무령왕릉은 벽돌무덤이다. 관산성 전사·사비 천도는 성왕, 서기 편찬은 근초고왕 때이다.","sec":2},{"id":"kh-q129","set":"삼국 시대","n":8,"s":1,"q":"[자료] 이 왕은 수도를 웅진에서 사비로 옮기고 국호를 남부여로 고쳤다. 중앙 관청을 22부로 정비하는 등 중흥을 꾀하였다.\n\n밑줄 그은 '이 왕'의 활동으로 옳은 것은?","o":["동진에서 불교를 받아들였다.","신라와 연합하여 한강 하류를 되찾았다.","익산에 미륵사를 창건하였다.","마한을 완전히 병합하였다.","오경박사를 처음 두었다."],"a":2,"e":"사비 천도와 남부여 개칭은 백제 성왕이다. 성왕은 신라 진흥왕과 연합하여 한강 하류를 회복하였으나 이후 관산성에서 전사하였다.","sec":2},{"id":"kh-q130","set":"삼국 시대","n":9,"s":1,"q":"[자료] 이 왕은 이차돈의 순교를 계기로 불교를 공인하였고, 율령을 반포하였으며 병부를 설치하였다. 건원이라는 독자적 연호도 사용하였다.\n\n밑줄 그은 '이 왕'의 업적으로 옳지 않은 것은?","o":["금관가야를 병합하였다.","불교를 공인하였다.","율령을 반포하였다.","화랑도를 국가 조직으로 개편하였다.","건원 연호를 사용하였다."],"a":4,"e":"불교 공인·율령 반포·병부 설치·금관가야 병합·건원 연호는 모두 신라 법흥왕의 업적이다. 화랑도를 국가 조직으로 정비한 것은 진흥왕이다.","sec":2},{"id":"kh-q131","set":"삼국 시대","n":10,"s":1,"q":"[자료] 김해 지역을 중심으로 성장한 이 나라는 시조 김수로왕의 건국 이야기가 전한다. 풍부한 철을 바탕으로 낙랑과 왜에 철을 수출하며 해상 교역을 주도하였다.\n\n밑줄 그은 '이 나라'로 옳은 것은?","o":["금관가야","고구려","백제","동예","옥저"],"a":1,"e":"김해, 김수로왕, 풍부한 철 생산과 중계 무역은 전기 가야 연맹을 주도한 금관가야의 특징이다.","sec":2},{"id":"kh-q132","set":"삼국 시대","n":11,"s":1,"q":"[자료] 전기 가야 연맹이 쇠퇴한 뒤, 고령 지역의 이 나라가 후기 가야 연맹을 이끌었다. 그러나 결국 신라 진흥왕에게 병합되었다.\n\n밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?","o":["8조법으로 사회를 유지하였다.","고령을 중심으로 후기 가야 연맹을 주도하였다.","한 무제의 공격으로 멸망하였다.","골품제라는 신분 제도를 두었다.","제가 회의에서 국가 중대사를 결정하였다."],"a":2,"e":"고령을 중심으로 후기 가야 연맹을 이끈 나라는 대가야이며 신라 진흥왕에게 병합되었다. 8조법은 고조선, 골품제는 신라, 제가 회의는 고구려이다.","sec":2},{"id":"kh-q133","set":"삼국 시대","n":12,"s":1,"q":"[자료] 수 양제가 대군을 이끌고 고구려를 침입하였다. 장수 을지문덕은 후퇴하는 척 적을 유인한 뒤 살수에서 적을 크게 무찔렀다.\n\n밑줄 그은 전투로 옳은 것은?","o":["살수 대첩","안시성 싸움","황산벌 전투","관산성 전투","매소성 전투"],"a":1,"e":"을지문덕이 수 양제의 군대를 살수(청천강)에서 크게 격파한 전투는 살수 대첩(612)이다. 안시성 싸움은 당, 매소성은 나당 전쟁 때이다.","sec":2},{"id":"kh-q134","set":"삼국 시대","n":13,"s":1,"q":"[자료] 이 인물은 정변을 일으켜 정권을 장악한 뒤 대막리지가 되어 권력을 독점하였다. 당의 침입에 맞서 강경한 대외 정책을 폈다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["연개소문","계백","을지문덕","김유신","이사부"],"a":1,"e":"정변으로 실권을 잡고 대막리지에 오른 인물은 고구려 연개소문이다. 그는 당에 강경책을 폈다. 계백은 백제, 김유신 이사부는 신라 장수이다.","sec":2},{"id":"kh-q135","set":"삼국 시대","n":14,"s":1,"q":"[자료] 백제의 장군 이 인물은 결사대 5천 명을 이끌고 황산벌에서 김유신의 신라군에 맞서 싸웠으나 끝내 패하였다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["계백","온달","성충","흑치상지","복신"],"a":1,"e":"황산벌에서 결사대를 이끌고 신라군과 싸운 백제 장군은 계백이다.","sec":2},{"id":"kh-q136","set":"삼국 시대","n":15,"s":1,"q":"[자료] 신라에는 혈통에 따라 관직 승진의 상한과 집·수레의 크기까지 제한하는 엄격한 신분 제도가 있었다.\n\n밑줄 그은 신분 제도로 옳은 것은?","o":["골품제","음서제","과거제","진대법","독서삼품과"],"a":1,"e":"혈통에 따라 관등 승진과 일상생활까지 규제한 신라의 신분 제도는 골품제이다. 6두품은 아무리 능력이 있어도 6관등 아찬까지만 오를 수 있었다.","sec":2},{"id":"kh-q137","set":"삼국 시대","n":16,"s":1,"q":"[자료] 선덕여왕 때 세워진 이 건축물은 하늘의 별을 관측하기 위한 시설로 알려져 있으며, 경주에 남아 있는 동양에서 가장 오래된 천문 관측대이다.\n\n밑줄 그은 건축물로 옳은 것은?","o":["첨성대","분황사 모전 석탑","황룡사 9층 목탑","석굴암","무령왕릉"],"a":1,"e":"신라 선덕여왕 때 축조된 천문 관측 시설은 첨성대이다.","sec":2},{"id":"kh-q138","set":"삼국 시대","n":17,"s":1,"q":"[자료] 백제 유적에서 출토된 이 유물은 도교와 불교 사상이 어우러진 대표적 금속 공예품으로, 정교한 뚜껑 장식과 봉황 조각이 특징이다.\n\n밑줄 그은 유물로 옳은 것은?","o":["백제 금동 대향로","금동 미륵보살 반가 사유상","칠지도","무용총 수렵도","성덕 대왕 신종"],"a":1,"e":"부여 능산리에서 출토된 백제의 대표 공예품은 백제 금동 대향로로 도교와 불교 사상이 반영되었다. 성덕 대왕 신종은 통일신라 유물이다.","sec":2},{"id":"kh-q139","set":"삼국 시대","n":18,"s":1,"q":"[자료] 충주(중원)에 세워진 이 비석은 고구려가 남한강 유역까지 진출하였음을 보여 주는 자료로, 신라를 동이라 부르고 매금이라 표현하였다.\n\n밑줄 그은 비석으로 옳은 것은?","o":["충주 고구려비","단양 신라 적성비","임신서기석","사택지적비","점제현 신사비"],"a":1,"e":"고구려의 남한강 유역 진출을 보여 주는 것은 충주 고구려비(중원 고구려비)이다. 단양 적성비는 신라 진흥왕의 영토 확장을 보여 준다.","sec":2},{"id":"kh-q140","set":"삼국 시대","n":19,"s":1,"q":"[자료] (가) 백제 근초고왕이 고구려 평양성을 공격하여 고국원왕을 전사시켰다.\n(나) 고구려 광개토대왕이 신라에 침입한 왜를 격퇴하였다.\n(다) 백제 성왕이 관산성 전투에서 전사하였다.\n\n(가)~(다)를 일어난 순서대로 옳게 나열한 것은?","o":["(가) - (나) - (다)","(가) - (다) - (나)","(나) - (가) - (다)","(다) - (가) - (나)","(나) - (다) - (가)"],"a":1,"e":"근초고왕의 평양성 공격(371) → 광개토대왕의 왜 격퇴(400) → 성왕 관산성 전사(554) 순이다.","sec":2},{"id":"kh-q141","set":"삼국 시대","n":20,"s":1,"q":"[자료] 이 왕은 나라를 세운 뒤 마한의 여러 세력을 정복하고 남해안까지 진출하였다. 또 고구려를 공격하여 황해도 일부를 차지하였으며, 왕위의 부자 상속을 확립하였다.\n\n밑줄 그은 '이 왕'의 활동으로 옳은 것은?","o":["평양성을 공격해 고국원왕을 전사시켰다.","웅진으로 도읍을 옮겼다.","동진에서 불교를 수용하였다.","22담로를 설치하였다.","익산에 미륵사를 세웠다."],"a":1,"e":"마한 정복과 부자 상속 확립, 고구려 평양성 공격으로 고국원왕을 전사시킨 왕은 백제 근초고왕이다. 불교 수용은 침류왕, 웅진 천도는 문주왕이다.","sec":2},{"id":"kh-q142","set":"삼국 시대","n":21,"s":1,"q":"[자료] 고구려의 무덤인 이 고분에는 씨름, 사냥, 무용 등 당시 생활 모습을 그린 벽화가 남아 있어 고구려인의 생활상을 알 수 있다.\n\n밑줄 그은 무덤 양식으로 옳은 것은?","o":["굴식 돌방무덤","돌무지덧널무덤","벽돌무덤","독무덤","돌무지무덤"],"a":1,"e":"벽화를 그릴 수 있는 고구려 후기 무덤 양식은 굴식 돌방무덤이다. 벽면과 천장에 그림을 그렸다. 신라의 돌무지덧널무덤은 벽화가 없다.","sec":2},{"id":"kh-q143","set":"삼국 시대","n":22,"s":1,"q":"[자료] 이 왕은 즉위 후 관등제와 공복을 정비하고 국호를 신라로 확정하였으며, 왕이라는 칭호를 사용하기 시작하였다.\n\n밑줄 그은 '이 왕'에 대한 설명으로 옳지 않은 것은?","o":["국호를 신라로 확정하였다.","왕 칭호를 처음 사용하였다.","우산국을 복속시켰다.","한강 유역을 차지하고 순수비를 세웠다.","순장을 금지하고 우경을 장려하였다."],"a":4,"e":"국호 신라 확정, 왕호 사용, 우산국 복속, 우경 장려는 모두 신라 지증왕의 업적이다. 한강 유역 확보와 순수비 건립은 진흥왕이다.","sec":2},{"id":"kh-q144","set":"삼국 시대","n":23,"s":1,"q":"[자료] 신라의 이 관직은 진골 귀족들이 모여 국가의 중대사를 만장일치로 결정하던 회의로, 상대등이 의장을 맡았다.\n\n밑줄 그은 회의로 옳은 것은?","o":["화백 회의","제가 회의","정사암 회의","도병마사","식목도감"],"a":1,"e":"만장일치제로 운영되고 상대등이 주재한 신라의 귀족 회의는 화백 회의이다. 고구려는 제가 회의, 백제는 정사암 회의이다.","sec":2},{"id":"kh-q145","set":"남북국 시대(통일신라·발해)","n":5,"s":1,"q":"[자료] 진골 출신으로 처음 왕위에 오른 이 인물은 당과 연합하여 백제를 멸망시키는 데 힘썼으며, 이후 삼국 통일의 기반을 마련하였다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["무열왕(김춘추)","문무왕","신문왕","법흥왕","진흥왕"],"a":1,"e":"최초의 진골 출신 왕으로 나당 연합을 이끌어 백제를 멸망시킨 인물은 태종 무열왕(김춘추)이다. 고구려 멸망과 삼국 통일 완성은 아들 문무왕 때이다.","sec":3},{"id":"kh-q146","set":"남북국 시대(통일신라·발해)","n":6,"s":1,"q":"[자료] 이 왕은 나당 전쟁을 승리로 이끌어 당의 세력을 몰아내고 삼국 통일을 완성하였다. 매소성과 기벌포에서 당군을 격파하였다.\n\n밑줄 그은 '이 왕'의 재위 시기에 있었던 사실로 옳은 것은?","o":["기벌포에서 당의 수군을 격파하였다.","김흠돌의 난을 진압하였다.","관료전을 지급하였다.","독서삼품과를 실시하였다.","국학을 설치하였다."],"a":1,"e":"매소성·기벌포 전투로 나당 전쟁을 승리하고 통일을 완성한 왕은 문무왕이다. 김흠돌의 난 진압·관료전·국학은 신문왕, 독서삼품과는 원성왕이다.","sec":3},{"id":"kh-q147","set":"남북국 시대(통일신라·발해)","n":7,"s":1,"q":"[자료] 통일 신라는 넓어진 영토와 백성을 다스리기 위해 지방 행정 조직을 새롭게 정비하였다. 옛 삼국의 땅에 고르게 주를 두고, 수도가 동남쪽에 치우친 것을 보완하기 위해 특수 행정 구역도 설치하였다.\n\n밑줄 그은 지방 행정 조직으로 옳은 것은?","o":["9주 5소경","5경 15부 62주","5도 양계","8도","전국 8도 23부"],"a":1,"e":"통일 신라의 지방 제도는 9주 5소경으로, 5소경은 수도의 편재성을 보완하였다. 5경 15부 62주는 발해의 지방 제도이다.","sec":3},{"id":"kh-q148","set":"남북국 시대(통일신라·발해)","n":8,"s":1,"q":"[자료] 통일 신라는 중앙군으로 이 부대를 편성하여 고구려·백제 유민과 말갈인까지 포함시켜 민족 통합을 꾀하였다.\n\n밑줄 그은 중앙군으로 옳은 것은?","o":["9서당","2군 6위","주진군","별무반","삼별초"],"a":1,"e":"통일 신라의 중앙군은 9서당으로, 신라인뿐 아니라 옛 삼국 유민과 말갈인을 포함시켜 민족 융합을 도모하였다. 지방군은 10정이다.","sec":3},{"id":"kh-q149","set":"남북국 시대(통일신라·발해)","n":9,"s":1,"q":"[자료] 이 왕은 유학 능력을 시험하여 관리를 뽑는 제도를 처음 마련하였다. 국학의 학생을 대상으로 유교 경전의 이해 수준을 상·중·하로 나누어 성적을 평가하였다.\n\n밑줄 그은 제도로 옳은 것은?","o":["독서삼품과","과거제","음서제","골품제","진대법"],"a":1,"e":"국학 학생의 유교 경전 이해도를 3등급으로 평가해 관리 선발에 참고한 제도는 원성왕 때의 독서삼품과이다.","sec":3},{"id":"kh-q150","set":"남북국 시대(통일신라·발해)","n":10,"s":1,"q":"[자료] 발해의 이 왕은 인안이라는 연호를 사용하고, 장문휴를 보내 당의 산둥 지방(등주)을 공격하는 등 대외적으로 강경책을 폈다.\n\n밑줄 그은 '이 왕'으로 옳은 것은?","o":["무왕","문왕","고왕(대조영)","선왕","성왕"],"a":1,"e":"인안 연호를 쓰고 장문휴로 하여금 당의 등주를 공격하게 한 발해의 왕은 무왕이다. 문왕은 대흥 연호와 친당 정책을 폈다.","sec":3},{"id":"kh-q151","set":"남북국 시대(통일신라·발해)","n":11,"s":1,"q":"[자료] 발해의 이 왕은 대흥이라는 연호를 사용하고 당과 친선 관계를 맺었으며, 수도를 상경 용천부로 옮기고 3성 6부의 중앙 관제를 정비하였다.\n\n밑줄 그은 '이 왕'에 대한 설명으로 옳은 것은?","o":["상경으로 도읍을 옮기고 대흥 연호를 사용하였다.","장문휴를 보내 당을 공격하였다.","고구려 유민을 모아 발해를 건국하였다.","해동성국이라 불릴 만큼 전성기를 이루었다.","5경 15부 62주를 처음 완성하였다."],"a":1,"e":"대흥 연호, 상경 천도, 친당 정책, 3성 6부 정비는 발해 문왕의 업적이다. 당 공격은 무왕, 건국은 대조영, 해동성국은 선왕 때이다.","sec":3},{"id":"kh-q152","set":"남북국 시대(통일신라·발해)","n":12,"s":1,"q":"[자료] 발해의 수도였던 이곳은 당의 장안성을 본떠 계획적으로 건설되었으며, 주작대로가 도시 중앙을 남북으로 가로질렀다.\n\n밑줄 그은 도읍으로 옳은 것은?","o":["상경 용천부","국내성","사비","금성","한성"],"a":1,"e":"당 장안성을 본떠 주작대로를 갖춘 발해의 수도는 상경 용천부이다.","sec":3},{"id":"kh-q153","set":"남북국 시대(통일신라·발해)","n":13,"s":1,"q":"[자료] 신라 하대인 이 시기에 진성여왕 때 사벌주(상주)에서 이 인물들이 세금 독촉에 반발하여 봉기하였다. 이는 전국적인 농민 봉기의 시작이 되었다.\n\n밑줄 그은 봉기로 옳은 것은?","o":["원종과 애노의 난","망이·망소이의 난","묘청의 난","김헌창의 난","홍경래의 난"],"a":1,"e":"진성여왕 때 사벌주에서 일어난 농민 봉기는 원종과 애노의 난(889)이다. 김헌창의 난은 헌덕왕 때 왕위 다툼에서 비롯된 반란이다.","sec":3},{"id":"kh-q154","set":"남북국 시대(통일신라·발해)","n":14,"s":1,"q":"[자료] 6두품 출신인 이 인물은 당에 유학하여 빈공과에 합격하고 황소의 난 때 격문을 지어 이름을 떨쳤다. 귀국 후 시무 10여 조를 올렸으나 받아들여지지 않았다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["최치원","설총","김대성","원효","의상"],"a":1,"e":"당 빈공과 합격, 토황소격문 작성, 시무 10여 조 건의로 알려진 6두품 유학자는 최치원이다. 설총은 이두 정리, 원효는 화쟁 사상으로 유명하다.","sec":3},{"id":"kh-q155","set":"남북국 시대(통일신라·발해)","n":15,"s":1,"q":"[자료] 신라 말 이 인물은 완산주(전주)를 도읍으로 삼아 후백제를 세우고, 중국의 후당·오월과 외교 관계를 맺었다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["견훤","궁예","왕건","대조영","김헌창"],"a":1,"e":"완산주를 도읍으로 후백제를 세운 인물은 견훤이다. 궁예는 후고구려(태봉)를 세웠고, 왕건은 고려를 건국하였다.","sec":3},{"id":"kh-q156","set":"남북국 시대(통일신라·발해)","n":16,"s":1,"q":"[자료] 신라 말 이 인물은 송악을 근거로 후고구려를 세운 뒤 국호를 마진, 태봉으로 바꾸고 철원으로 도읍을 옮겼다. 광평성 등 관제를 마련하였다.\n\n밑줄 그은 '이 인물'로 옳은 것은?","o":["궁예","견훤","왕건","최치원","장보고"],"a":1,"e":"후고구려를 세우고 국호를 마진·태봉으로 바꾸었으며 철원 천도와 광평성 설치를 한 인물은 궁예이다.","sec":3},{"id":"kh-q157","set":"남북국 시대(통일신라·발해)","n":17,"s":1,"q":"[자료] (가) 무열왕이 즉위하여 나당 연합을 주도하였다.\n(나) 원성왕이 독서삼품과를 실시하였다.\n(다) 진성여왕 때 원종과 애노가 봉기하였다.\n\n(가)~(다)를 일어난 순서대로 옳게 나열한 것은?","o":["(가) - (나) - (다)","(가) - (다) - (나)","(나) - (가) - (다)","(다) - (나) - (가)","(나) - (다) - (가)"],"a":1,"e":"무열왕 즉위(654) → 원성왕 독서삼품과(788) → 진성여왕 때 원종·애노의 난(889) 순이다.","sec":3},{"id":"kh-q158","set":"남북국 시대(통일신라·발해)","n":18,"s":1,"q":"[자료] 통일 신라의 이 승려는 화엄 사상을 정립하고 부석사를 창건하였으며, 화엄일승법계도를 지어 교단을 형성하였다.\n\n밑줄 그은 '이 승려'로 옳은 것은?","o":["의상","원효","혜초","자장","김대성"],"a":1,"e":"화엄 사상을 정리하고 부석사를 세웠으며 화엄일승법계도를 지은 승려는 의상이다. 원효는 무애가와 일심 사상, 혜초는 왕오천축국전으로 유명하다.","sec":3},{"id":"kh-q159","set":"고려 시대","n":7,"s":1,"q":"[자료] 짐이 죽은 후 나라를 다스릴 후손들에게 훈계를 남기니, 첫째는 불교의 힘을 빌려 나라를 세웠음을 잊지 말 것이며, 넷째는 거란의 풍속을 본받지 말라는 것이다.\n\n밑줄 그은 훈계를 남긴 왕의 업적으로 옳은 것은?","o":["과거제를 처음 실시하였다.","흑창을 설치하여 빈민을 구제하였다.","전민변정도감을 두었다.","경국대전을 반포하였다.","독서삼품과를 시행하였다."],"a":2,"e":"제시문은 태조 왕건의 훈요 10조이다. 태조는 흑창을 설치해 빈민을 구제하였다. 과거제는 광종, 전민변정도감은 공민왕, 경국대전은 조선 성종, 독서삼품과는 신라 원성왕이다.","sec":4},{"id":"kh-q160","set":"고려 시대","n":8,"s":1,"q":"태조 왕건이 지방 세력을 통제하기 위해 실시한 정책으로 옳은 것을 고른 것은? (ㄱ. 사심관 제도 ㄴ. 기인 제도 ㄷ. 노비안검법 ㄹ. 12목 설치)","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"e":"태조는 지방 호족을 견제하기 위해 사심관 제도와 기인 제도를 실시하였다. 노비안검법은 광종, 12목 설치는 성종의 정책이다.","sec":4},{"id":"kh-q161","set":"고려 시대","n":9,"s":1,"q":"[자료] 거란의 소손녕이 대군을 이끌고 침입하자 그가 외교 담판에 나섰다. 그는 고려가 고구려를 계승하였음을 내세우며 송과 교류를 끊고 거란과 통교할 것을 약속하였다.\n\n이 담판의 결과로 옳은 것은?","o":["강동 6주를 획득하였다.","동북 9성을 쌓았다.","쌍성총관부를 회복하였다.","4군 6진을 개척하였다.","천리장성을 완성하였다."],"a":1,"e":"서희는 거란 소손녕과의 외교 담판으로 강동 6주를 획득하였다. 동북 9성은 윤관, 4군 6진은 조선 세종 때이다.","sec":4},{"id":"kh-q162","set":"고려 시대","n":10,"s":1,"q":"[자료] 거란이 다시 대규모로 침입하였으나, 그가 이끄는 고려군이 귀주에서 거란군을 크게 물리쳤다. 이로써 거란의 침입은 마무리되었다.\n\n밑줄 그은 인물로 옳은 것은?","o":["강감찬","윤관","최영","김윤후","서희"],"a":1,"e":"거란의 3차 침입 때 귀주 대첩을 이끈 인물은 강감찬이다. 윤관은 여진 정벌, 김윤후는 처인성 전투에서 활약하였다.","sec":4},{"id":"kh-q163","set":"고려 시대","n":11,"s":1,"q":"[자료] 신이 여진을 정벌하기 위해 특수 부대를 조직할 것을 청하오니, 신기군, 신보군, 항마군으로 편성하겠나이다.\n\n밑줄 그은 부대를 조직한 인물의 활동으로 옳은 것은?","o":["동북 9성을 축조하였다.","강동 6주를 확보하였다.","4군을 개척하였다.","화통도감을 설치하였다.","삼별초를 조직하였다."],"a":1,"e":"별무반(신기군·신보군·항마군)을 조직한 인물은 윤관이다. 윤관은 여진을 정벌하고 동북 9성을 축조하였다.","sec":4},{"id":"kh-q164","set":"고려 시대","n":12,"s":1,"q":"고려 시대 국가 재정의 근간을 이루었던 것으로, 관리에게 등급에 따라 전지와 시지를 지급한 토지 제도는?","o":["전시과","과전법","직전법","녹읍","정전"],"a":1,"e":"전시과는 관직 등급에 따라 전지(곡물)와 시지(땔감)를 지급한 고려의 토지 제도이다. 과전법·직전법은 조선, 녹읍·정전은 통일 신라이다.","sec":4},{"id":"kh-q165","set":"고려 시대","n":13,"s":1,"q":"[자료] 정중부, 이의방 등이 보현원에서 정변을 일으켜 다수의 문신을 제거하고 권력을 장악하였다. 이후 무신들이 정권을 주도하는 시대가 열렸다.\n\n이 정변 이후에 일어난 사실로 옳지 않은 것은?","o":["최충헌이 교정도감을 설치하였다.","망이·망소이가 봉기하였다.","만적이 신분 해방을 도모하였다.","묘청이 서경 천도를 주장하였다.","최우가 정방을 설치하였다."],"a":4,"e":"제시문은 무신정변(1170)이다. 묘청의 서경 천도 운동(1135)은 무신정변 이전의 사건이므로 옳지 않다. 나머지는 모두 무신 집권기의 사실이다.","sec":4},{"id":"kh-q166","set":"고려 시대","n":14,"s":1,"q":"[자료] 최고 집권자가 국정을 총괄하는 최고 권력 기구를 설치하고, 사병 집단인 도방을 확대하여 신변을 경호하였다.\n\n밑줄 그은 기구를 설치한 인물로 옳은 것은?","o":["최충헌","정중부","이의민","최우","경대승"],"a":1,"e":"교정도감을 설치하고 도방을 확대한 인물은 최충헌이다. 그의 아들 최우는 정방과 서방을 설치하였다.","sec":4},{"id":"kh-q167","set":"고려 시대","n":15,"s":1,"q":"[자료] 경인년 이래로 높은 벼슬이 천예에서 많이 나왔다. 장상에 어찌 씨가 따로 있겠는가. 때가 오면 누구나 할 수 있는 것이다.\n\n이와 같이 주장하며 봉기를 계획한 인물로 옳은 것은?","o":["만적","망이","김보당","이비","조위총"],"a":1,"e":"최충헌의 사노비였던 만적은 신분 해방을 주장하며 봉기를 계획하였다. '왕후장상의 씨가 따로 있느냐'는 구호로 유명하다.","sec":4},{"id":"kh-q168","set":"고려 시대","n":16,"s":1,"q":"[자료] 몽골과의 강화 이후 개경 환도가 결정되자, 이에 반발한 삼별초가 배중손을 중심으로 진도와 제주도로 근거지를 옮겨 가며 항쟁을 이어 갔다.\n\n밑줄 그은 부대에 대한 설명으로 옳은 것은?","o":["최우가 조직한 군사 조직에서 비롯되었다.","별무반을 모체로 편성되었다.","9서당 10정으로 편제되었다.","훈련도감의 지휘를 받았다.","2군 6위의 중앙군이었다."],"a":1,"e":"삼별초는 최우가 조직한 야별초에서 비롯된 군사 조직으로, 개경 환도에 반발해 대몽 항쟁을 이어 갔다. 별무반은 윤관, 9서당 10정은 통일 신라, 훈련도감은 조선이다.","sec":4},{"id":"kh-q169","set":"고려 시대","n":17,"s":1,"q":"원 간섭기 고려 사회의 모습으로 옳지 않은 것은?","o":["정동행성이 설치되었다.","권문세족이 대농장을 소유하였다.","응방을 통해 매를 징발하였다.","공녀가 원으로 끌려갔다.","전민변정도감이 처음 설치되어 개혁이 완수되었다."],"a":5,"e":"원 간섭기에는 정동행성 설치, 권문세족의 성장, 응방 운영, 공녀 징발 등이 이루어졌다. 전민변정도감은 여러 차례 설치되었으나 개혁이 완수되지는 못하였으므로 옳지 않다.","sec":4},{"id":"kh-q170","set":"고려 시대","n":18,"s":1,"q":"[자료] 예성강 하구에 위치한 이 항구는 고려의 국제 무역항으로, 송·아라비아 상인까지 드나들며 고려(Corea)라는 이름이 서방에 알려지는 계기가 되었다.\n\n밑줄 그은 '이 항구'로 옳은 것은?","o":["벽란도","당항성","울산항","제물포","부산포"],"a":1,"e":"벽란도는 예성강 하구의 고려 국제 무역항으로, 송·아라비아 상인이 왕래하였다. 당항성·울산항은 신라의 무역항이다.","sec":4},{"id":"kh-q171","set":"고려 시대","n":19,"s":1,"q":"[자료] 그는 송과 요에서 유학하고 돌아와 국청사를 중심으로 교종을 바탕으로 선종을 통합하고자 하였으며, 교관겸수를 주장하였다.\n\n밑줄 그은 인물로 옳은 것은?","o":["의천","지눌","혜심","요세","의상"],"a":1,"e":"천태종을 개창하고 교관겸수를 주장한 인물은 대각국사 의천이다. 지눌은 수선사 결사와 정혜쌍수·돈오점수를 주장하였다.","sec":4},{"id":"kh-q172","set":"고려 시대","n":20,"s":1,"q":"[자료] 그는 불교계의 타락을 비판하며 순천 송광사를 중심으로 결사 운동을 전개하였고, 선종을 중심으로 교종을 포용하는 정혜쌍수와 돈오점수를 내세웠다.\n\n밑줄 그은 인물로 옳은 것은?","o":["지눌","의천","균여","도선","일연"],"a":1,"e":"수선사(정혜) 결사를 이끌고 정혜쌍수·돈오점수를 주장한 인물은 보조국사 지눌이다.","sec":4},{"id":"kh-q173","set":"고려 시대","n":21,"s":1,"q":"[자료] 이 책은 현존하는 우리나라에서 가장 오래된 역사서로, 김부식 등이 왕명을 받아 유교적 합리주의 사관에 입각하여 기전체로 편찬하였다.\n\n밑줄 그은 '이 책'으로 옳은 것은?","o":["삼국사기","삼국유사","제왕운기","동국통감","고려사"],"a":1,"e":"김부식이 기전체로 편찬한 현존 최고(最古)의 역사서는 삼국사기이다. 삼국유사는 일연, 제왕운기는 이승휴의 저술이다.","sec":4},{"id":"kh-q174","set":"고려 시대","n":22,"s":1,"q":"[자료] 이 책은 일연이 편찬한 것으로, 불교사를 중심으로 단군 신화를 비롯한 여러 설화와 향가 등을 수록하고 있다.\n\n밑줄 그은 '이 책'에 대한 설명으로 옳은 것은?","o":["단군의 건국 이야기가 실려 있다.","김부식이 왕명으로 편찬하였다.","기전체 형식으로 서술되었다.","고구려 계승 의식이 강조된 편년체이다.","조선 왕조의 정통성을 밝혔다."],"a":1,"e":"삼국유사는 일연이 편찬한 역사서로 단군의 건국 이야기(단군 신화)를 수록하였다. 김부식·기전체는 삼국사기에 대한 설명이다.","sec":4},{"id":"kh-q175","set":"고려 시대","n":23,"s":1,"q":"공민왕의 반원 자주 정책으로 옳지 않은 것은?","o":["정동행성 이문소를 폐지하였다.","쌍성총관부를 공격하여 철령 이북 땅을 되찾았다.","친원파인 기철 일파를 제거하였다.","몽골식 변발과 호복을 금지하였다.","전시과를 처음 제정하였다."],"a":5,"e":"공민왕은 정동행성 이문소 폐지, 쌍성총관부 수복, 기철 제거, 변발·호복 금지 등 반원 자주 정책을 폈다. 전시과는 고려 초 경종 때 처음 제정되었으므로 옳지 않다.","sec":4},{"id":"kh-q176","set":"고려 시대","n":24,"s":1,"q":"[자료] 성종은 최승로가 올린 개혁안을 받아들여 유교 정치 이념을 확립하고, 전국의 주요 지역에 지방관을 파견하였다.\n\n밑줄 그은 왕이 지방에 지방관을 파견하며 설치한 것으로 옳은 것은?","o":["12목","5소경","9주","8도","23부"],"a":1,"e":"성종은 시무 28조를 수용하여 전국 주요 지역에 12목을 설치하고 지방관을 파견하였다. 5소경·9주는 통일 신라, 8도는 조선이다.","sec":4},{"id":"kh-q177","set":"조선 전기","n":6,"s":1,"q":"[자료] 그는 재상 중심의 정치를 주장하며 조선경국전, 불씨잡변 등을 저술하였고, 한양 도성 건설을 주도하였다.\n\n밑줄 그은 인물로 옳은 것은?","o":["정도전","권근","조준","하륜","정몽주"],"a":1,"e":"재상 중심 정치를 주장하고 조선경국전과 불씨잡변을 저술한 인물은 정도전이다. 그는 제1차 왕자의 난 때 이방원에게 제거되었다.","sec":5},{"id":"kh-q178","set":"조선 전기","n":7,"s":1,"q":"[자료] 김종서, 황보인 등을 제거하고 정권을 장악한 그는 조카를 몰아내고 왕위에 올랐으며, 이후 6조 직계제를 부활시켰다.\n\n밑줄 그은 왕의 업적으로 옳은 것은?","o":["직전법을 실시하였다.","훈민정음을 창제하였다.","대동법을 처음 시행하였다.","탕평비를 세웠다.","장용영을 설치하였다."],"a":1,"e":"계유정난으로 집권한 세조는 현직 관리에게만 수조권을 지급하는 직전법을 실시하였다. 훈민정음은 세종, 대동법은 광해군, 탕평비·장용영은 영·정조이다.","sec":5},{"id":"kh-q179","set":"조선 전기","n":8,"s":1,"q":"[자료] 이 법전은 세조 때 편찬을 시작하여 성종 때 완성·반포되었으며, 조선 통치의 기본 법전이 되었다.\n\n밑줄 그은 '이 법전'으로 옳은 것은?","o":["경국대전","대전회통","속대전","경제육전","대명률"],"a":1,"e":"세조 때 편찬을 시작하여 성종 때 완성·반포된 조선의 기본 법전은 경국대전이다. 속대전은 영조, 대전회통은 고종 때 편찬되었다.","sec":5},{"id":"kh-q180","set":"조선 전기","n":9,"s":1,"q":"조선 전기에 일어난 4대 사화를 순서대로 바르게 나열한 것은?","o":["무오사화 - 갑자사화 - 기묘사화 - 을사사화","갑자사화 - 무오사화 - 을사사화 - 기묘사화","무오사화 - 기묘사화 - 갑자사화 - 을사사화","기묘사화 - 무오사화 - 갑자사화 - 을사사화","갑자사화 - 무오사화 - 기묘사화 - 을사사화"],"a":1,"e":"4대 사화는 무오사화(1498, 연산군) - 갑자사화(1504, 연산군) - 기묘사화(1519, 중종) - 을사사화(1545, 명종) 순으로 일어났다.","sec":5},{"id":"kh-q181","set":"조선 전기","n":10,"s":1,"q":"[자료] 김일손이 스승 김종직의 조의제문을 사초에 실은 것이 발단이 되어, 훈구파가 사림파를 대대적으로 숙청하였다.\n\n밑줄 그은 사건으로 옳은 것은?","o":["무오사화","갑자사화","기묘사화","을사사화","경신환국"],"a":1,"e":"김종직의 조의제문과 김일손의 사초가 발단이 된 사건은 무오사화(1498)이다. 조의제문은 세조의 왕위 찬탈을 비판한 글로 해석되었다.","sec":5},{"id":"kh-q182","set":"조선 전기","n":11,"s":1,"q":"[자료] 사림 세력은 지방에서 이것을 세워 선현에 대한 제사와 성리학 교육을 담당하게 하였다. 최초의 것은 주세붕이 세운 백운동으로, 이황의 건의로 소수라는 사액을 받았다.\n\n밑줄 그은 '이것'에 대한 설명으로 옳은 것은?","o":["사림의 세력 기반이 되었다.","전국의 부·목·군·현에 하나씩 설치된 관학이었다.","성균관의 하급 관리를 양성하였다.","국가가 운영하는 최고 교육 기관이었다.","기술관을 양성하는 잡학 교육을 담당하였다."],"a":1,"e":"제시문은 서원이다. 서원은 사림이 세운 사립 교육 기관으로 향촌에서 사림의 세력 기반이 되었다. 관학이자 최고 교육 기관은 성균관, 지방 관학은 향교이다.","sec":5},{"id":"kh-q183","set":"조선 전기","n":12,"s":1,"q":"[자료] 이것은 향촌 사회의 자치 규약으로, 덕업상권, 과실상규, 예속상교, 환난상휼의 네 가지 덕목을 바탕으로 사림이 향촌 질서를 주도하는 기반이 되었다.\n\n밑줄 그은 '이것'으로 옳은 것은?","o":["향약","향안","유향소","향청","경재소"],"a":1,"e":"덕업상권 등 4대 덕목을 바탕으로 한 향촌 자치 규약은 향약이다. 향약은 사림의 향촌 지배력을 강화하는 수단이 되었다.","sec":5},{"id":"kh-q184","set":"조선 전기","n":13,"s":1,"q":"조선 전기 사림 세력에 대한 설명으로 옳은 것은?","o":["3사의 언관직에 진출하여 훈구파를 비판하였다.","계유정난을 계기로 권력을 장악하였다.","불교와 도교를 국가 통치 이념으로 삼았다.","조선 건국을 주도하여 개국 공신이 되었다.","대농장을 소유한 권문세족에서 성장하였다."],"a":1,"e":"사림은 3사의 언관직에 진출하여 훈구파의 비리를 비판하며 성장하였다. 계유정난·개국 공신·대농장 소유는 훈구파와 관련되며, 권문세족은 고려 후기 세력이다.","sec":5},{"id":"kh-q185","set":"조선 전기","n":14,"s":1,"q":"[자료] 1592년 왜군이 침입하자, 그는 진주성에서 관군과 백성을 이끌고 왜군의 대규모 공격을 막아 내는 큰 승리를 거두었다.\n\n밑줄 그은 전투로 옳은 것은?","o":["진주 대첩","행주 대첩","한산도 대첩","명량 해전","황산 대첩"],"a":1,"e":"김시민이 이끈 진주 대첩(1592)은 임진왜란 3대 대첩의 하나이다. 행주 대첩은 권율, 한산도·명량은 이순신, 황산 대첩은 고려 말 이성계의 전투이다.","sec":5},{"id":"kh-q186","set":"조선 전기","n":15,"s":1,"q":"[자료] 임진왜란 당시 그는 행주산성에서 관군과 백성을 지휘하여 왜군의 총공세를 물리치는 큰 승리를 거두었다.\n\n밑줄 그은 인물로 옳은 것은?","o":["권율","김시민","곽재우","조헌","신립"],"a":1,"e":"행주 대첩(1593)을 이끈 인물은 도원수 권율이다. 김시민은 진주 대첩, 곽재우는 의병장으로 활약하였다.","sec":5},{"id":"kh-q187","set":"조선 전기","n":16,"s":1,"q":"[자료] 임진왜란 때 경상도 의령에서 스스로 군사를 일으켜 붉은 옷을 입고 활약하여 홍의장군이라 불린 그는 대표적인 의병장이다.\n\n밑줄 그은 인물로 옳은 것은?","o":["곽재우","고경명","정문부","유정","휴정"],"a":1,"e":"경상도 의령에서 봉기하여 홍의장군으로 불린 의병장은 곽재우이다. 유정(사명대사)·휴정(서산대사)은 승병장이다.","sec":5},{"id":"kh-q188","set":"조선 전기","n":17,"s":1,"q":"임진왜란 중에 설치되어 포수·사수·살수의 삼수병으로 편제된 군사 기구로 옳은 것은?","o":["훈련도감","장용영","별무반","2군 6위","속오군"],"a":1,"e":"임진왜란 중 유성룡의 건의로 설치된 훈련도감은 포수·사수·살수의 삼수병으로 편제되었다. 장용영은 정조, 별무반은 고려 윤관 때이다.","sec":5},{"id":"kh-q189","set":"조선 전기","n":18,"s":1,"q":"[자료] 명과 후금 사이에서 어느 한쪽에 치우치지 않는 실리적 외교를 펼친 그는, 강홍립을 도원수로 삼아 파병하되 상황을 보아 대응하도록 하였다.\n\n밑줄 그은 왕으로 옳은 것은?","o":["광해군","선조","인조","효종","연산군"],"a":1,"e":"명과 후금 사이에서 중립 외교를 펼친 왕은 광해군이다. 그는 강홍립에게 상황에 따라 대처하도록 명하였고, 대동법을 처음 실시하였다.","sec":5},{"id":"kh-q190","set":"조선 전기","n":19,"s":1,"q":"[자료] 청이 군신 관계를 요구하며 침입하자, 인조는 남한산성으로 피란하여 항전하였으나 결국 삼전도에서 청 태종에게 항복하였다.\n\n이 전쟁으로 옳은 것은?","o":["병자호란","정묘호란","임진왜란","정유재란","나선 정벌"],"a":1,"e":"인조가 남한산성에서 항전하다 삼전도에서 항복한 전쟁은 병자호란(1636)이다. 정묘호란(1627)은 후금이 형제 관계를 요구하며 일으킨 전쟁이다.","sec":5},{"id":"kh-q191","set":"조선 전기","n":20,"s":1,"q":"[자료] 이 지도는 조선 태종 때 제작된 것으로, 현존하는 동양에서 가장 오래된 세계 지도이다. 중국을 중심으로 유럽과 아프리카까지 그려져 있다.\n\n밑줄 그은 '이 지도'로 옳은 것은?","o":["혼일강리역대국도지도","대동여지도","동국지도","곤여만국전도","천상열차분야지도"],"a":1,"e":"태종 때 제작된 현존 동양 최고(最古)의 세계 지도는 혼일강리역대국도지도이다. 대동여지도·동국지도는 조선 후기, 곤여만국전도는 서양식 세계 지도이다.","sec":5},{"id":"kh-q192","set":"조선 전기","n":21,"s":1,"q":"[자료] 세종은 한양을 기준으로 천체 운행을 계산한 이 역법서를 편찬하게 하여, 우리 실정에 맞는 역법을 갖추게 하였다.\n\n밑줄 그은 '이 역법서'로 옳은 것은?","o":["칠정산","향약집성방","농사직설","동의보감","의방유취"],"a":1,"e":"한양을 기준으로 천체 운행을 계산한 세종 때의 역법서는 칠정산이다. 농사직설은 농서, 향약집성방·의방유취는 의서이다.","sec":5},{"id":"kh-q193","set":"조선 후기","n":6,"s":1,"q":"[자료] 본래 변방의 국방 문제를 논의하기 위한 임시 회의 기구로 설치되었으나, 임진왜란을 거치면서 국정 전반을 총괄하는 최고 기구로 자리 잡았다.\n\n밑줄 그은 이 기구에 대한 설명으로 옳은 것은?","o":["흥선 대원군 집권기에 기능이 강화되었다.","왕권을 강화하기 위해 정조가 처음 설치하였다.","세도 정치기에 이르러 국왕의 권한을 뒷받침하였다.","의정부와 6조의 기능이 유명무실해지는 결과를 가져왔다.","고려 시대 도병마사가 개편된 기구이다."],"a":4,"e":"제시문은 비변사이다. 을묘왜변을 계기로 상설화되고 임진왜란 이후 최고 기구로 확대되면서 의정부와 6조의 기능이 유명무실해졌다. 흥선 대원군은 오히려 비변사를 축소·폐지하였다.","sec":6},{"id":"kh-q194","set":"조선 후기","n":7,"s":1,"q":"[자료] 효종의 죽음을 두고 자의 대비가 상복을 몇 년 입을 것인지를 놓고 서인과 남인이 대립하였다. 이후 효종 비의 죽음 때에도 같은 논쟁이 재현되었다.\n\n이와 같은 논쟁이 전개된 왕대의 사실로 옳은 것은?","o":["기해예송과 갑인예송이 일어났다.","무오사화와 갑자사화가 일어났다.","이괄의 난으로 도성이 함락되었다.","위화도 회군으로 정권이 교체되었다.","훈구와 사림이 처음으로 대립하였다."],"a":1,"e":"자의 대비의 복상 문제를 둘러싼 두 차례 논쟁은 현종 대의 기해예송(1659)과 갑인예송(1674)이다. 사화는 조선 전기, 이괄의 난은 인조, 위화도 회군은 고려 말의 일이다.","sec":6},{"id":"kh-q195","set":"조선 후기","n":8,"s":1,"q":"[자료] 이 왕은 남인과 서인을 번갈아 등용하며 정국을 급격히 바꾸는 방식으로 왕권을 강화하였다. 경신환국, 기사환국, 갑술환국이 이 시기에 일어났다.\n\n밑줄 그은 이 왕의 재위 시기에 있었던 사실로 옳은 것은?","o":["장용영을 설치하여 군사권을 장악하였다.","백두산정계비를 세워 청과 국경을 정하였다.","훈민정음을 창제하여 반포하였다.","4군 6진을 개척하여 영토를 넓혔다.","독서삼품과를 실시하였다."],"a":2,"e":"환국(경신·기사·갑술)을 주도한 왕은 숙종이다. 숙종 대에 청과의 국경을 정한 백두산정계비(1712)가 세워졌다. 장용영은 정조, 훈민정음·4군 6진은 세종, 독서삼품과는 통일 신라 원성왕 때이다.","sec":6},{"id":"kh-q196","set":"조선 후기","n":9,"s":1,"q":"[자료] 인조 때 실시된 이 제도는 풍년과 흉년에 관계없이 토지 1결당 쌀 4~6두로 전세를 고정하였다.\n\n밑줄 그은 이 제도로 옳은 것은?","o":["영정법","균역법","과전법","호포제","방납"],"a":1,"e":"토지 1결당 쌀 4~6두로 전세를 고정한 것은 인조 대의 영정법이다. 균역법은 군포 부담을 줄인 영조 대 제도, 과전법은 고려 말 토지 제도, 호포제는 흥선 대원군의 개혁이다.","sec":6},{"id":"kh-q197","set":"조선 후기","n":10,"s":1,"q":"[자료] 모내기법이 널리 보급되면서 김매는 노동력이 줄어 한 사람이 넓은 토지를 경작하는 것이 가능해졌다. 이에 따라 일부 농민은 부농으로 성장하였다.\n\n위와 같은 변화가 나타난 시기의 경제 모습으로 옳지 않은 것은?","o":["담배, 인삼 등 상품 작물이 재배되었다.","광작이 성행하여 농민층이 분화되었다.","일부 지역에서 이모작이 확대되었다.","정전제를 실시하여 농민에게 토지를 나누어 주었다.","쌀의 상품화가 진전되었다."],"a":4,"e":"모내기법(이앙법) 보급에 따른 광작·상품 작물 재배·이모작은 조선 후기 농업의 특징이다. 정전제는 통일 신라 성덕왕 때 시행된 토지 제도로 조선 후기와 무관하다.","sec":6},{"id":"kh-q198","set":"조선 후기","n":11,"s":1,"q":"[자료] 조선 후기에 이르러 전국적으로 유통된 이 화폐는 상품 화폐 경제의 발달을 촉진하였다.\n\n밑줄 그은 이 화폐로 옳은 것은?","o":["상평통보","명도전","건원중보","해동통보","백동화"],"a":1,"e":"조선 후기에 전국적으로 유통된 화폐는 상평통보이다. 명도전은 철기 시대, 건원중보와 해동통보는 고려, 백동화는 대한 제국 시기의 화폐이다.","sec":6},{"id":"kh-q199","set":"조선 후기","n":12,"s":1,"q":"[자료] 조선 후기에는 각 지방에서 활동하는 사상들이 성장하였다. 이들은 지역과 특산물을 기반으로 대규모 상업 활동을 벌였다.\n\n조선 후기 사상과 그 활동에 대한 설명으로 옳지 않은 것은?","o":["송상은 개성을 근거지로 송방을 두고 인삼을 거래하였다.","경강상인은 한강을 중심으로 미곡 운송에 종사하였다.","만상은 의주를 근거지로 청과의 무역을 주도하였다.","내상은 동래를 근거지로 일본과 무역하였다.","보부상은 시전을 통해 왕실에 물품을 조달하는 특권을 가졌다."],"a":5,"e":"보부상은 장시를 돌며 물품을 유통한 행상 조직으로, 시전을 통해 왕실에 물품을 조달하던 특권 상인과는 다르다. 송상(개성)·경강상인(한강)·만상(의주)·내상(동래)의 활동은 모두 옳은 설명이다.","sec":6},{"id":"kh-q200","set":"조선 후기","n":13,"s":1,"q":"[자료] 부유한 농민이나 상인들은 재산을 바쳐 (가) 을/를 받아 신분을 상승시키거나, 족보를 사고 위조하기도 하였다. 이로 인해 양반의 수가 늘고 상민과 노비의 수가 줄어들었다.\n\n(가)에 들어갈 내용으로 옳은 것은?","o":["공명첩","호패","교지","공인","시전"],"a":1,"e":"이름을 비워 두고 관직·신분을 파는 문서는 공명첩이다. 부농·상인들은 공명첩과 족보 위조 등으로 신분을 상승시켜 신분제가 동요하였다. 호패는 신분 증명, 교지는 임명장이다.","sec":6},{"id":"kh-q201","set":"조선 후기","n":14,"s":1,"q":"[자료] 그는 토지 제도의 개혁을 주장하며, 한 가정의 생활을 유지하는 데 필요한 최소한의 토지인 영업전을 정하고 그 매매를 금지하자고 하였다.\n\n밑줄 그은 그와 그의 저술로 옳은 것은?","o":["이익 - 곽우록","유형원 - 반계수록","홍대용 - 의산문답","박제가 - 북학의","박지원 - 열하일기"],"a":1,"e":"영업전을 설정하여 매매를 금지하는 한전론을 주장한 인물은 성호 이익이며, 대표 저술은 곽우록이다. 유형원은 균전론(반계수록), 홍대용·박제가·박지원은 북학파(상공업 중심)이다.","sec":6},{"id":"kh-q202","set":"조선 후기","n":15,"s":1,"q":"[자료] 청에 다녀온 뒤 그는 청의 발달한 문물을 배워야 한다고 주장하며, 재물을 우물에 비유하여 소비를 통해 생산을 촉진해야 한다고 강조하였다.\n\n밑줄 그은 그의 저술로 옳은 것은?","o":["북학의","반계수록","성호사설","목민심서","동사강목"],"a":1,"e":"소비를 우물에 비유하며 절약보다 소비를 강조하고 청 문물 수용을 주장한 인물은 박제가이며, 그의 저술은 북학의이다. 반계수록은 유형원, 성호사설은 이익, 목민심서는 정약용, 동사강목은 안정복의 저술이다.","sec":6},{"id":"kh-q203","set":"조선 후기","n":16,"s":1,"q":"[자료] 발해의 역사를 우리 역사로 인식하고, 신라와 발해가 병존한 시기를 이르는 용어를 처음 사용한 역사서이다.\n\n밑줄 그은 이 역사서와 저자로 옳은 것은?","o":["발해고 - 유득공","동사강목 - 안정복","연려실기술 - 이긍익","해동역사 - 한치윤","동국통감 - 서거정"],"a":1,"e":"발해를 우리 역사로 보고 남북국이라는 용어를 처음 사용한 저술은 유득공의 발해고이다. 동사강목은 안정복의 편년체 통사, 연려실기술은 이긍익의 기사본말체 역사서이다.","sec":6},{"id":"kh-q204","set":"조선 후기","n":17,"s":1,"q":"[자료] 그는 전국을 직접 답사한 자료를 바탕으로 산맥과 하천, 도로망을 정밀하게 표시한 지도를 목판으로 제작하였다.\n\n밑줄 그은 그가 제작한 지도로 옳은 것은?","o":["대동여지도","혼일강리역대국도지도","동국지도","곤여만국전도","천상열차분야지도"],"a":1,"e":"김정호가 목판으로 제작한 지도는 대동여지도이다. 혼일강리역대국도지도는 조선 초기 세계 지도, 곤여만국전도는 서양식 세계 지도, 천상열차분야지도는 천문도이다.","sec":6},{"id":"kh-q205","set":"조선 후기","n":18,"s":1,"q":"[자료] 조선 후기에는 서민의 의식이 성장하면서 그들의 감정과 현실을 반영한 문화가 발달하였다.\n\n조선 후기 서민 문화에 대한 설명으로 옳지 않은 것은?","o":["김홍도와 신윤복 등이 풍속화를 그렸다.","춘향전, 홍길동전 등 한글 소설이 널리 읽혔다.","판소리와 탈춤이 유행하였다.","청화 백자가 널리 사용되었다.","이차돈의 순교를 소재로 한 불교 미술이 유행하였다."],"a":5,"e":"풍속화, 한글 소설, 판소리·탈춤, 청화 백자는 모두 조선 후기 서민 문화의 발달을 보여 준다. 이차돈의 순교는 신라 법흥왕 대의 불교 공인과 관련된 것으로 조선 후기와 무관하다.","sec":6},{"id":"kh-q206","set":"조선 후기","n":19,"s":1,"q":"[자료] 삼정의 문란으로 고통받던 농민들이 진주에서 봉기한 것을 시작으로 전국 각지에서 봉기가 잇따랐다. 정부는 사태 수습을 위해 (가) 을/를 설치하였다.\n\n(가)에 들어갈 기구로 옳은 것은?","o":["삼정이정청","훈련도감","교정도감","도평의사사","통리기무아문"],"a":1,"e":"1862년 임술 농민 봉기(진주 민란 등)에 대한 대책으로 정부는 삼정이정청을 설치하였다. 훈련도감은 임진왜란 중 설치된 군영, 통리기무아문은 개항 이후의 개화 기구이다.","sec":6},{"id":"kh-q207","set":"조선 후기","n":20,"s":1,"q":"[자료] 몰락 양반 출신인 그는 사람이 곧 하늘이라는 사상을 바탕으로 새로운 종교를 창시하였으나, 세상을 어지럽힌다는 죄목으로 처형되었다.\n\n밑줄 그은 그와 그가 창시한 종교로 옳은 것은?","o":["최제우 - 동학","최시형 - 천도교","나철 - 대종교","손병희 - 원불교","안창호 - 대성교"],"a":1,"e":"인내천 사상을 바탕으로 동학을 창시한 인물은 최제우이며, 그는 혹세무민의 죄로 처형되었다. 최시형은 2대 교주로 교리를 정리하였고, 천도교로의 개칭은 손병희 때의 일이다.","sec":6},{"id":"kh-q208","set":"조선 후기","n":21,"s":1,"q":"[자료] 조선 후기의 다음 사건을 일어난 순서대로 바르게 나열한 것은?\n(가) 기해예송이 일어났다.\n(나) 임술 농민 봉기가 일어났다.\n(다) 백두산정계비가 건립되었다.\n\n(가)~(다)를 순서대로 옳게 나열한 것은?","o":["(가) - (다) - (나)","(가) - (나) - (다)","(다) - (가) - (나)","(나) - (가) - (다)","(다) - (나) - (가)"],"a":1,"e":"기해예송(1659, 현종) - 백두산정계비(1712, 숙종) - 임술 농민 봉기(1862, 철종)의 순서이다.","sec":6},{"id":"kh-q209","set":"개항기(근대)","n":7,"s":1,"q":"[자료] 프랑스 함대가 강화도를 침입하여 외규장각의 도서와 문화재를 약탈해 갔다. 이 과정에서 한성근, 양헌수 부대가 항전하였다.\n\n밑줄 그은 이 사건으로 옳은 것은?","o":["병인양요","신미양요","운요호 사건","제너럴셔먼호 사건","오페르트 도굴 사건"],"a":1,"e":"프랑스군이 외규장각 도서를 약탈하고 양헌수·한성근이 항전한 사건은 병인양요(1866)이다. 신미양요는 미국, 운요호 사건은 일본, 오페르트 도굴은 독일 상인과 관련된다.","sec":7},{"id":"kh-q210","set":"개항기(근대)","n":8,"s":1,"q":"[자료] 미국 상선이 대동강을 거슬러 올라와 통상을 요구하며 행패를 부리자, 평안도 관찰사 박규수와 평양 관민이 이 배를 불태워 침몰시켰다.\n\n밑줄 그은 이 사건이 빌미가 되어 일어난 사건으로 옳은 것은?","o":["신미양요","병인양요","운요호 사건","임오군란","갑신정변"],"a":1,"e":"제너럴셔먼호 사건(1866)을 구실로 미국이 강화도를 침략한 사건이 신미양요(1871)이다. 신미양요 때 어재연 부대가 광성보에서 항전하였다.","sec":7},{"id":"kh-q211","set":"개항기(근대)","n":9,"s":1,"q":"[자료] 조선이 서양 국가와 맺은 최초의 조약으로, 거중조정과 최혜국 대우 조항이 포함되었다. 청의 알선으로 체결되었다.\n\n밑줄 그은 이 조약으로 옳은 것은?","o":["조미 수호 통상 조약","강화도 조약","조프 수호 통상 조약","제물포 조약","한성 조약"],"a":1,"e":"서양 국가와 맺은 최초의 조약이며 거중조정·최혜국 대우 조항을 담고 청의 알선으로 체결된 것은 조미 수호 통상 조약(1882)이다. 강화도 조약은 일본과 맺은 최초의 근대적 조약이다.","sec":7},{"id":"kh-q212","set":"개항기(근대)","n":10,"s":1,"q":"[자료] 구식 군인들이 신식 군대인 별기군과의 차별 대우와 밀린 급료에 불만을 품고 봉기하였다. 이 사건의 결과 (가) 이/가 체결되었다.\n\n(가)에 들어갈 조약으로 옳은 것은?","o":["제물포 조약","강화도 조약","한성 조약","톈진 조약","을사늑약"],"a":1,"e":"구식 군인 차별 대우에서 비롯된 임오군란(1882)의 결과, 일본과 제물포 조약이 체결되어 배상금 지불과 일본 공사관 경비병 주둔이 허용되었다. 한성 조약은 갑신정변, 톈진 조약은 청·일 간 조약이다.","sec":7},{"id":"kh-q213","set":"개항기(근대)","n":11,"s":1,"q":"[자료] 동학 농민군이 백산에서 봉기하여 황토현 전투에서 승리한 뒤 전주성을 점령하였다. 이후 정부와 화약을 맺고 개혁안 실천을 위해 자치 기구를 설치하였다.\n\n이 화약의 결과로 옳은 것은?","o":["전라도 일대에 집강소가 설치되었다.","군국기무처가 설치되었다.","단발령이 시행되었다.","대한 제국이 수립되었다.","통감부가 설치되었다."],"a":1,"e":"전주 화약(1894) 이후 동학 농민군은 전라도 일대에 자치 기구인 집강소를 설치하고 폐정 개혁을 추진하였다. 군국기무처와 단발령은 갑오·을미개혁, 대한 제국은 1897년, 통감부는 을사늑약 이후이다.","sec":7},{"id":"kh-q214","set":"개항기(근대)","n":12,"s":1,"q":"[자료] 동학 농민군은 일본군을 몰아내기 위해 다시 봉기하였으나, 공주 부근의 이 전투에서 우세한 화력을 앞세운 일본군과 관군에 크게 패하였다.\n\n밑줄 그은 이 전투로 옳은 것은?","o":["우금치 전투","황토현 전투","황룡촌 전투","봉오동 전투","청산리 전투"],"a":1,"e":"제2차 동학 농민 운동 때 공주 부근에서 일본군·관군에게 대패한 전투는 우금치 전투(1894)이다. 봉오동·청산리 전투는 1920년 만주에서의 독립군 전투이다.","sec":7},{"id":"kh-q215","set":"개항기(근대)","n":13,"s":1,"q":"[자료] 군국기무처를 중심으로 추진된 이 개혁에서는 신분제와 과거제를 폐지하고, 재정을 탁지아문으로 일원화하였으며, 조혼을 금지하였다.\n\n밑줄 그은 이 개혁에 대한 설명으로 옳지 않은 것은?","o":["연호로 건양을 사용하였다.","신분제와 노비제가 폐지되었다.","과거제를 폐지하였다.","재정을 탁지아문으로 일원화하였다.","조혼을 금지하고 과부의 재가를 허용하였다."],"a":1,"e":"제시문은 제1차 갑오개혁(1894)이다. 신분제·과거제 폐지, 재정 일원화, 조혼 금지 등이 그 내용이다. 건양 연호 사용은 을미개혁(1895) 때의 일이다.","sec":7},{"id":"kh-q216","set":"개항기(근대)","n":14,"s":1,"q":"[자료] 고종이 종묘에 나아가 국정 개혁의 기본 강령을 반포하였다. 여기에는 청에 의존하는 생각을 버리고 자주 독립의 기초를 세운다는 내용이 담겼다.\n\n밑줄 그은 이 강령으로 옳은 것은?","o":["홍범 14조","헌의 6조","교육 입국 조서","조선 혁명 선언","독립 선언서"],"a":1,"e":"1895년 고종이 종묘에서 반포한 근대적 개혁 강령은 홍범 14조이다. 헌의 6조는 관민 공동회에서 결의된 것, 교육 입국 조서는 근대 교육의 방향을 제시한 조서이다.","sec":7},{"id":"kh-q217","set":"개항기(근대)","n":15,"s":1,"q":"[자료] 명성 황후가 일본 자객에게 시해된 사건 이후, 이 개혁이 추진되어 태양력을 채택하고 단발령을 시행하였다.\n\n밑줄 그은 이 개혁이 시행된 이후에 일어난 사건으로 옳은 것은?","o":["고종이 러시아 공사관으로 거처를 옮겼다.","운요호 사건이 일어났다.","강화도 조약이 체결되었다.","병인양요가 일어났다.","제너럴셔먼호 사건이 일어났다."],"a":1,"e":"을미개혁(1895)의 단발령·태양력 채택은 을미의병을 불러왔고, 이어 1896년 고종이 러시아 공사관으로 피신하는 아관파천이 일어났다. 나머지 사건은 모두 을미개혁 이전의 일이다.","sec":7},{"id":"kh-q218","set":"개항기(근대)","n":16,"s":1,"q":"[자료] 환궁한 고종은 황제로 즉위하고 국호를 대한 제국으로 선포하였다. 이후 옛것을 근본으로 하고 새것을 참고한다는 원칙 아래 개혁을 추진하였다.\n\n밑줄 그은 이 개혁에 대한 설명으로 옳은 것은?","o":["대한국 국제를 반포하여 황제권을 강화하였다.","군국기무처를 설치하였다.","공사 노비법을 혁파하였다.","과거제를 폐지하였다.","전국을 8도로 나누었다."],"a":1,"e":"광무개혁은 구본신참의 원칙 아래 추진되었으며, 1899년 대한국 국제를 반포하여 황제의 전제권을 규정하였다. 군국기무처·노비법 혁파·과거제 폐지는 갑오개혁의 내용이다.","sec":7},{"id":"kh-q219","set":"개항기(근대)","n":17,"s":1,"q":"[자료] 서양의 통상 요구에 맞서 유생들은 성리학적 질서를 지키고 서양과 일본을 배척할 것을 주장하였다. 이러한 흐름은 이후 항일 의병으로 이어졌다.\n\n이러한 사상적 흐름을 이르는 말로 옳은 것은?","o":["위정척사","동도서기","문명개화","실력 양성","애국 계몽"],"a":1,"e":"바른 것을 지키고 그릇된 것을 물리친다는 뜻으로, 성리학 질서 수호와 외세 배척을 주장한 흐름은 위정척사이다. 이는 최익현 등을 거쳐 항일 의병 운동으로 계승되었다.","sec":7},{"id":"kh-q220","set":"개항기(근대)","n":18,"s":1,"q":"[자료] 대한 제국의 외교권을 강탈한 조약이 강제 체결되자, 전국 각지에서 유생과 농민들이 의병을 일으켰다. 특히 최익현, 신돌석 등이 활약하였다.\n\n밑줄 그은 이 의병에 대한 설명으로 옳은 것은?","o":["평민 출신 의병장 신돌석이 활약하였다.","단발령에 반발하여 일어났다.","13도 창의군을 결성해 서울 진공 작전을 폈다.","고종의 해산 권고 조칙으로 해산하였다.","자유시 참변으로 큰 타격을 입었다."],"a":1,"e":"을사늑약(1905)에 반발해 일어난 을사의병에서는 최익현, 평민 의병장 신돌석 등이 활약하였다. 단발령 반발은 을미의병, 13도 창의군·서울 진공 작전은 정미의병의 특징이다.","sec":7},{"id":"kh-q221","set":"개항기(근대)","n":19,"s":1,"q":"[자료] 일제가 대한 제국의 군대를 강제로 해산하자, 해산 군인들이 의병에 합류하면서 전투력이 강화되었다. 이후 각지의 의병 부대가 연합하여 서울 진공 작전을 전개하였다.\n\n밑줄 그은 이 의병에 대한 설명으로 옳은 것은?","o":["13도 창의군을 결성하였다.","을미사변을 계기로 처음 일어났다.","전주 화약을 체결하였다.","집강소를 설치하였다.","단발령 시행에 반발하였다."],"a":1,"e":"1907년 군대 해산 이후 일어난 정미의병은 해산 군인이 합류하여 13도 창의군을 결성하고 서울 진공 작전을 전개하였다. 을미사변·단발령 반발은 을미의병, 전주 화약·집강소는 동학 농민 운동과 관련된다.","sec":7},{"id":"kh-q222","set":"개항기(근대)","n":20,"s":1,"q":"[자료] 안창호, 양기탁 등이 중심이 되어 비밀 결사로 조직된 이 단체는 공화정 수립을 목표로 하였으며, 대성 학교와 오산 학교를 세우고 태극 서관과 자기 회사를 운영하였다.\n\n밑줄 그은 이 단체로 옳은 것은?","o":["신민회","보안회","독립 협회","대한 자강회","헌정 연구회"],"a":1,"e":"공화정을 지향한 비밀 결사로 대성·오산 학교, 태극 서관, 자기 회사를 운영한 단체는 신민회(1907)이다. 보안회는 일제의 황무지 개간권 요구를 저지한 단체이다.","sec":7},{"id":"kh-q223","set":"개항기(근대)","n":21,"s":1,"q":"[자료] 나라가 진 빚을 국민의 힘으로 갚자는 취지에서 대구에서 시작된 이 운동은 서상돈 등이 주도하고 대한매일신보 등 언론의 후원으로 전국으로 확산되었다.\n\n밑줄 그은 이 운동으로 옳은 것은?","o":["국채 보상 운동","물산 장려 운동","브나로드 운동","민립 대학 설립 운동","형평 운동"],"a":1,"e":"대구에서 서상돈 등이 시작하고 대한매일신보의 후원으로 확산된 국채 상환 운동은 국채 보상 운동(1907)이다. 물산 장려·민립 대학 설립·브나로드 운동은 1920~30년대의 일이다.","sec":7},{"id":"kh-q224","set":"개항기(근대)","n":22,"s":1,"q":"[자료] 1883년 정부는 함경도 원산에 근대적 학교를 세워 외국어와 근대 학문, 무술 등을 가르쳤다. 이는 우리나라 최초의 근대적 사립 학교로 평가된다.\n\n밑줄 그은 이 학교로 옳은 것은?","o":["원산 학사","육영 공원","배재 학당","이화 학당","대성 학교"],"a":1,"e":"함경도 덕원(원산) 지역민이 세운 최초의 근대적 사립 학교는 원산 학사(1883)이다. 육영 공원은 정부가 세운 관립 학교, 배재·이화 학당은 선교사가 세운 학교이다.","sec":7},{"id":"kh-q225","set":"개항기(근대)","n":23,"s":1,"q":"[자료] 1899년에 개통된 이 철도는 우리나라 최초의 철도로, 노량진과 제물포를 잇는 구간이었다.\n\n밑줄 그은 이 철도로 옳은 것은?","o":["경인선","경부선","경의선","경원선","호남선"],"a":1,"e":"노량진~제물포를 연결한 우리나라 최초의 철도는 경인선(1899)이다. 경부선(1905), 경의선(1906)은 그 이후에 개통되었다.","sec":7},{"id":"kh-q226","set":"개항기(근대)","n":24,"s":1,"q":"[자료] 다음 개항기 사건들을 일어난 순서대로 바르게 나열한 것은?\n(가) 임오군란이 일어났다.\n(나) 아관파천이 단행되었다.\n(다) 을사늑약이 체결되었다.\n\n(가)~(다)를 순서대로 옳게 나열한 것은?","o":["(가) - (나) - (다)","(가) - (다) - (나)","(나) - (가) - (다)","(다) - (나) - (가)","(나) - (다) - (가)"],"a":1,"e":"임오군란(1882) - 아관파천(1896) - 을사늑약(1905)의 순서이다.","sec":7},{"id":"kh-q227","set":"일제 강점기","n":7,"s":1,"q":"[자료] 조선 총독부는 한국인에게만 적용되는 태형령을 제정하고, 헌병이 경찰 업무를 맡아 즉결 처분권을 행사하였다. 관리와 교원까지 제복을 입고 칼을 차게 하였다.\n\n밑줄 그은 시기 일제의 통치 방식으로 옳은 것은?","o":["보통 경찰제를 실시하였다.","치안 유지법을 처음 제정하였다.","헌병 경찰을 앞세워 무단 통치를 하였다.","국민학교 명칭을 사용하게 하였다.","황국 신민 서사를 암송하게 하였다."],"a":3,"e":"조선 태형령과 헌병 경찰 즉결 처분은 1910년대 무단 통치의 특징이다. 보통 경찰제와 국민학교 명칭, 황국 신민 서사는 이후 시기의 정책이다.","sec":8},{"id":"kh-q228","set":"일제 강점기","n":8,"s":1,"q":"1910년대 일제가 실시한 정책으로 옳지 않은 것은?","o":["회사령을 제정하여 회사 설립을 허가제로 하였다.","조선 태형령을 시행하였다.","헌병 경찰 제도를 운영하였다.","치안 유지법으로 사상을 통제하였다.","제1차 조선 교육령으로 보통학교 수업 연한을 단축하였다."],"a":4,"e":"치안 유지법은 1925년에 제정되어 사회주의 운동 등을 탄압한 법으로, 1910년대 무단 통치기의 정책이 아니다. 나머지는 모두 1910년대의 조치이다.","sec":8},{"id":"kh-q229","set":"일제 강점기","n":9,"s":1,"q":"[자료] 3.1 운동을 계기로 일제는 통치 방식을 바꾸었다. 총독에 문관도 임명할 수 있게 하고 보통 경찰제로 전환하였으나, 실제로는 경찰 수를 크게 늘려 감시를 강화하였다.\n\n밑줄 그은 통치 방식에 대한 설명으로 옳은 것은?","o":["실제로는 민족 분열을 노린 기만적 통치였다.","토지 조사 사업을 처음 시작하였다.","회사령을 제정하여 산업을 통제하였다.","국가 총동원법을 공포하였다.","황국 신민화 정책을 본격 추진하였다."],"a":1,"e":"3.1 운동 이후 1920년대의 이른바 문화 통치는 겉으로 유화책을 내세웠으나 실제로는 친일파 육성과 민족 분열을 노린 기만적 통치였다. 문관 총독은 한 명도 임명되지 않았다.","sec":8},{"id":"kh-q230","set":"일제 강점기","n":10,"s":1,"q":"[자료] 이 정부는 상하이에서 수립되어 연통제와 교통국을 통해 국내와 연락하고 독립운동 자금을 모았다. 미국에는 구미 위원부를 두어 외교 활동을 벌였다.\n\n밑줄 그은 정부에 대한 설명으로 옳은 것은?","o":["만민 공동회를 개최하였다.","독립 공채를 발행하여 자금을 마련하였다.","척화비를 전국에 건립하였다.","훈련도감을 설치하였다.","교정도감을 통해 인사권을 장악하였다."],"a":2,"e":"연통제, 교통국, 구미 위원부는 대한민국 임시 정부의 활동이다. 임시 정부는 독립 공채를 발행하여 독립운동 자금을 마련하였다. 나머지는 다른 시대의 사실이다.","sec":8},{"id":"kh-q231","set":"일제 강점기","n":11,"s":1,"q":"[자료] 임시 정부의 활동이 침체되자 1923년 독립운동의 방향을 논의하기 위한 회의가 열렸다. 정부를 해체하고 새 조직을 만들자는 주장과 그대로 두고 개편하자는 주장이 맞서 결렬되었다.\n\n밑줄 그은 회의로 옳은 것은?","o":["국민 대표 회의","서울 진공 작전","좌우 합작 위원회","남북 협상","건국 준비 위원회"],"a":1,"e":"1923년 개조파와 창조파가 대립한 회의는 국민 대표 회의이다. 결렬되면서 임시 정부의 침체가 심화되었다.","sec":8},{"id":"kh-q232","set":"일제 강점기","n":12,"s":1,"q":"[자료] 1926년 순종의 인산일을 기하여 학생들이 격문을 뿌리고 만세 시위를 계획하였다. 이 운동은 사회주의 세력과 민족주의 세력이 함께 준비하여 민족 유일당 운동에 영향을 주었다.\n\n밑줄 그은 운동으로 옳은 것은?","o":["6.10 만세 운동","브나로드 운동","국채 보상 운동","형평 운동","민립 대학 설립 운동"],"a":1,"e":"1926년 순종 인산일을 계기로 일어난 것은 6.10 만세 운동이다. 이 운동은 좌우 세력의 연대 경험을 제공하여 신간회 결성의 배경이 되었다.","sec":8},{"id":"kh-q233","set":"일제 강점기","n":13,"s":1,"q":"[자료] 1929년 나주에서 통학 열차 안 한국인 여학생을 일본인 학생이 희롱한 사건이 발단이 되어 광주에서 대규모 시위가 일어났다. 이 운동은 전국으로 확산되어 3.1 운동 이후 최대의 항일 학생 운동이 되었다.\n\n밑줄 그은 운동에 대한 설명으로 옳은 것은?","o":["신간회가 진상 조사단을 파견하여 지원하였다.","통감부 설치의 계기가 되었다.","대한매일신보의 후원을 받았다.","이완용 등 을사오적을 처단하였다.","교정청 설치를 이끌어냈다."],"a":1,"e":"광주 학생 항일 운동에 대해 신간회는 진상 조사단을 파견하고 민중 대회를 계획하는 등 지원하였다. 나머지는 시기가 맞지 않는 사실이다.","sec":8},{"id":"kh-q234","set":"일제 강점기","n":14,"s":1,"q":"[자료] 김원봉을 중심으로 만주에서 결성된 이 단체는 신채호가 작성한 선언을 활동 지침으로 삼았다. 김익상, 나석주 등이 조선 총독부와 동양 척식 주식회사 등에 폭탄을 던졌다.\n\n밑줄 그은 단체와 관련된 선언으로 옳은 것은?","o":["조선 혁명 선언","기미 독립 선언","대한 독립 선언","2.8 독립 선언","좌우 합작 7원칙"],"a":1,"e":"김원봉의 의열단은 신채호가 작성한 조선 혁명 선언을 지침으로 삼아 폭력 투쟁을 전개하였다. 나머지 선언들은 의열단과 직접 관련이 없다.","sec":8},{"id":"kh-q235","set":"일제 강점기","n":15,"s":1,"q":"[자료] 1920년 6월 홍범도가 이끄는 대한 독립군 등 독립군 연합 부대가 만주에서 일본군을 크게 격파하였다. 이 전투는 봉오동 일대에서 벌어졌다.\n\n밑줄 그은 전투에 대한 설명으로 옳은 것은?","o":["홍범도의 대한 독립군이 주도하였다.","자유시 참변으로 이어진 직접 원인이었다.","한국광복군이 참여하였다.","봉오동 전투 이후 훈련도감이 설치되었다.","일본이 조선을 강제 병합하는 계기가 되었다."],"a":1,"e":"봉오동 전투는 1920년 홍범도의 대한 독립군이 주도하여 일본군을 격파한 전투이다. 한국광복군은 1940년에 창설되었으므로 관련이 없다.","sec":8},{"id":"kh-q236","set":"일제 강점기","n":16,"s":1,"q":"다음 사건을 일어난 순서대로 옳게 나열한 것은? (가) 봉오동 전투 (나) 6.10 만세 운동 (다) 광주 학생 항일 운동 (라) 국가 총동원법 공포","o":["(가)-(나)-(다)-(라)","(나)-(가)-(다)-(라)","(가)-(다)-(나)-(라)","(나)-(가)-(라)-(다)","(가)-(나)-(라)-(다)"],"a":1,"e":"봉오동 전투(1920) 다음 6.10 만세 운동(1926), 광주 학생 항일 운동(1929), 국가 총동원법 공포(1938) 순서이다.","sec":8},{"id":"kh-q237","set":"일제 강점기","n":17,"s":1,"q":"[자료] 1930년대 만주에서 지청천이 지휘한 이 부대는 중국 호로군과 연합하여 쌍성보, 대전자령 등지에서 일본군을 격파하였다.\n\n밑줄 그은 부대로 옳은 것은?","o":["한국 독립군","조선 의용대","별기군","한국광복군","조선 혁명군"],"a":1,"e":"지청천이 지휘하고 중국 호로군과 연합하여 쌍성보, 대전자령에서 승리한 부대는 한국 독립군이다. 남만주에서 양세봉이 이끈 부대는 조선 혁명군이다.","sec":8},{"id":"kh-q238","set":"일제 강점기","n":18,"s":1,"q":"[자료] 1938년 김원봉의 주도로 중국 관내에서 결성된 이 부대는 중국 국민당의 지원을 받아 창설된 최초의 한인 무장 조직으로 평가된다. 이후 일부 세력이 화북으로 이동하였다.\n\n밑줄 그은 부대로 옳은 것은?","o":["조선 의용대","대한 독립군","북로 군정서","한국 독립군","조선 혁명군"],"a":1,"e":"1938년 김원봉이 중국 관내에서 결성한 부대는 조선 의용대이다. 중국 국민당의 지원을 받은 관내 최초의 한인 무장 부대였다.","sec":8},{"id":"kh-q239","set":"일제 강점기","n":19,"s":1,"q":"[자료] 1940년 대한민국 임시 정부는 충칭에서 이 군대를 창설하였다. 태평양 전쟁이 일어나자 일본에 선전 포고를 하고, 미국 전략 정보국과 협력하여 국내 진공 작전을 준비하였다.\n\n밑줄 그은 군대에 대한 설명으로 옳은 것은?","o":["대한민국 임시 정부의 정규군으로 창설되었다.","봉오동 전투를 승리로 이끌었다.","자유시 참변으로 큰 피해를 입었다.","청산리에서 일본군을 격파하였다.","2.8 독립 선언을 발표하였다."],"a":1,"e":"한국광복군은 1940년 충칭에서 대한민국 임시 정부의 정규군으로 창설되었다. 봉오동, 청산리, 자유시 참변은 1920년대의 사실이다.","sec":8},{"id":"kh-q240","set":"일제 강점기","n":20,"s":1,"q":"[자료] 일제는 1938년 이 법을 공포하여 인적, 물적 자원을 전쟁 수행에 총동원할 수 있는 근거를 마련하였다. 이에 따라 강제 징용, 징병, 공출 등이 자행되었다.\n\n밑줄 그은 법으로 옳은 것은?","o":["국가 총동원법","회사령","치안 유지법","조선 태형령","토지 조사령"],"a":1,"e":"1938년 공포되어 인적, 물적 자원의 총동원 근거가 된 법은 국가 총동원법이다. 이를 바탕으로 징용, 징병, 공출, 위안부 동원 등이 이루어졌다.","sec":8},{"id":"kh-q241","set":"일제 강점기","n":21,"s":1,"q":"민족 말살 통치 시기(1930년대 후반 이후)의 정책으로 옳지 않은 것은?","o":["황국 신민 서사를 암송하게 하였다.","신사 참배를 강요하였다.","조선어 과목을 사실상 폐지하였다.","회사령을 제정하여 회사 설립을 허가제로 하였다.","일본식 성명 강요를 실시하였다."],"a":4,"e":"회사령은 1910년대 무단 통치기의 정책이다. 황국 신민 서사, 신사 참배 강요, 조선어 폐지, 일본식 성명 강요는 모두 민족 말살 통치기의 정책이다.","sec":8},{"id":"kh-q242","set":"일제 강점기","n":22,"s":1,"q":"[자료] 이 학회는 한글 맞춤법 통일안과 표준어를 제정하고 우리말 큰사전 편찬을 추진하였다. 일제는 회원들을 독립운동 혐의로 검거하여 활동을 탄압하였다.\n\n밑줄 그은 학회로 옳은 것은?","o":["조선어 학회","독립 협회","대한 자강회","보안회","신민회"],"a":1,"e":"한글 맞춤법 통일안, 표준어 제정, 우리말 큰사전 편찬을 추진하다 일제에 탄압받은 단체는 조선어 학회이다.","sec":8},{"id":"kh-q243","set":"일제 강점기","n":23,"s":1,"q":"[자료] 그는 역사를 아와 비아의 투쟁으로 보고 조선상고사를 저술하였으며, 낭가 사상을 강조하여 민족 정신을 일깨우고자 하였다.\n\n밑줄 그은 인물로 옳은 것은?","o":["신채호","백남운","안재홍","이병도","정인보"],"a":1,"e":"역사를 아와 비아의 투쟁으로 규정하고 조선상고사를 저술한 민족주의 사학자는 신채호이다. 박은식은 한국통사, 백남운은 사회 경제 사학으로 구별된다.","sec":8},{"id":"kh-q244","set":"일제 강점기","n":24,"s":1,"q":"[자료] 1915년 대구에서 결성된 이 비밀 결사는 군자금을 모아 독립운동을 지원하고 친일 부호를 처단하는 활동을 전개하였다. 공화정 수립을 지향하였다.\n\n밑줄 그은 단체로 옳은 것은?","o":["대한 광복회","신간회","한인 애국단","의열단","조선 어학회"],"a":1,"e":"1915년 대구에서 결성되어 군자금 모금과 친일 부호 처단, 공화정 수립을 지향한 국내 비밀 결사는 대한 광복회이다.","sec":8},{"id":"kh-q245","set":"현대","n":6,"s":1,"q":"[자료] 1945년 8월 15일 광복 직후 여운형은 조선 건국 준비 위원회를 조직하여 치안과 행정을 담당하고 새 국가 수립을 준비하였다.\n\n밑줄 그은 조직에 대한 설명으로 옳은 것은?","o":["광복 직후 치안과 행정을 담당하였다.","반민족 행위자를 처벌하기 위해 만들어졌다.","5.10 총선거로 구성되었다.","좌우 합작 7원칙을 발표하였다.","유엔 감시하에 수립되었다."],"a":1,"e":"조선 건국 준비 위원회는 광복 직후 여운형 등이 조직하여 치안과 행정을 담당하고 건국을 준비한 단체이다. 나머지는 다른 기구나 사건에 해당한다.","sec":9},{"id":"kh-q246","set":"현대","n":7,"s":1,"q":"[자료] 여운형과 김규식이 중심이 되어 좌우익의 대립을 극복하고 통일 정부를 세우기 위해 전개한 운동이다. 미군정의 지원 아래 7원칙을 발표하였으나 두 지도자의 활동이 좌절되며 성과를 거두지 못하였다.\n\n밑줄 그은 운동으로 옳은 것은?","o":["좌우 합작 운동","물산 장려 운동","브나로드 운동","새마을 운동","국채 보상 운동"],"a":1,"e":"여운형과 김규식이 중심이 되어 통일 정부 수립을 위해 7원칙을 발표한 것은 좌우 합작 운동이다.","sec":9},{"id":"kh-q247","set":"현대","n":8,"s":1,"q":"[자료] 단독 정부 수립에 반대한 그는 1948년 남한만의 총선거를 앞두고 북측 지도자들과 회담하기 위해 38선을 넘어 평양을 방문하였다.\n\n밑줄 그은 인물이 추진한 활동으로 옳은 것은?","o":["남북 협상","반민 특위 활동","발췌 개헌","한일 협정 체결","베트남 파병"],"a":1,"e":"김구는 단독 정부 수립에 반대하여 김규식과 함께 평양을 방문, 남북 협상을 추진하였다. 나머지는 김구와 관련이 없는 사건들이다.","sec":9},{"id":"kh-q248","set":"현대","n":9,"s":1,"q":"[자료] 1948년 5월 10일 유엔 한국 임시 위원단의 감시 아래 남한에서 총선거가 실시되어 제헌 국회가 구성되었다. 이 국회는 헌법을 제정하고 초대 대통령을 선출하였다.\n\n밑줄 그은 국회의 활동으로 옳은 것은?","o":["반민족 행위 처벌법을 제정하였다.","유신 헌법을 통과시켰다.","한일 기본 조약을 비준하였다.","금융 실명제를 도입하였다.","남북 기본 합의서를 채택하였다."],"a":1,"e":"제헌 국회는 반민족 행위 처벌법을 제정하고 반민 특위를 구성하였다. 나머지는 이후 시기의 사실이다.","sec":9},{"id":"kh-q249","set":"현대","n":10,"s":1,"q":"다음 사건을 일어난 순서대로 옳게 나열한 것은? (가) 8.15 광복 (나) 5.10 총선거 (다) 대한민국 정부 수립 (라) 6.25 전쟁 발발","o":["(가)-(나)-(다)-(라)","(가)-(다)-(나)-(라)","(나)-(가)-(다)-(라)","(가)-(나)-(라)-(다)","(가)-(라)-(나)-(다)"],"a":1,"e":"8.15 광복(1945), 5.10 총선거(1948.5), 대한민국 정부 수립(1948.8), 6.25 전쟁 발발(1950) 순서이다.","sec":9},{"id":"kh-q250","set":"현대","n":11,"s":1,"q":"[자료] 1953년 7월 판문점에서 이 협정이 체결되어 3년간 계속된 전쟁이 중지되었다. 군사 분계선과 비무장 지대가 설정되었다.\n\n밑줄 그은 협정 이후의 사실로 옳은 것은?","o":["한미 상호 방위 조약이 체결되었다.","좌우 합작 운동이 전개되었다.","조선 건국 준비 위원회가 조직되었다.","모스크바 3국 외상 회의가 열렸다.","5.10 총선거가 실시되었다."],"a":1,"e":"6.25 전쟁의 정전 협정(1953.7) 직후 한미 상호 방위 조약이 체결되었다. 나머지는 모두 정전 협정 이전의 사실이다.","sec":9},{"id":"kh-q251","set":"현대","n":12,"s":1,"q":"이승만 정부 시기에 있었던 개헌으로 옳은 것을 모두 고른 것은? (가) 발췌 개헌 (나) 사사오입 개헌 (다) 유신 헌법 (라) 3선 개헌","o":["(가), (나)","(가), (다)","(나), (라)","(다), (라)","(가), (라)"],"a":1,"e":"발췌 개헌(1952)과 사사오입 개헌(1954)은 이승만 정부 시기의 개헌이다. 유신 헌법과 3선 개헌은 박정희 정부 시기의 일이다.","sec":9},{"id":"kh-q252","set":"현대","n":13,"s":1,"q":"[자료] 4.19 혁명으로 이승만 정부가 붕괴한 뒤 내각 책임제와 양원제를 골자로 하는 개헌이 이루어졌다. 이후 총선거를 통해 이 내각이 출범하였다.\n\n밑줄 그은 내각으로 옳은 것은?","o":["장면 내각","허정 과도 정부","제헌 국회","군사 혁명 위원회","국가 재건 최고 회의"],"a":1,"e":"4.19 혁명 이후 내각 책임제 개헌을 통해 출범한 것은 장면 내각(제2공화국)이다.","sec":9},{"id":"kh-q253","set":"현대","n":14,"s":1,"q":"[자료] 1965년 정부는 일본과 국교를 정상화하는 조약을 체결하였다. 이에 앞서 굴욕 외교라며 반대하는 대규모 시위가 일어났다.\n\n밑줄 그은 조약에 반대하여 일어난 시위로 옳은 것은?","o":["6.3 시위","4.19 혁명","6월 민주 항쟁","부마 민주 항쟁","5.18 민주화 운동"],"a":1,"e":"1964~1965년 한일 협정에 반대하여 일어난 시위는 6.3 시위이다.","sec":9},{"id":"kh-q254","set":"현대","n":15,"s":1,"q":"[자료] 박정희 정부는 근면, 자조, 협동을 내세우며 농촌 환경 개선과 소득 증대를 목표로 이 운동을 전국적으로 전개하였다.\n\n밑줄 그은 운동으로 옳은 것은?","o":["새마을 운동","브나로드 운동","물산 장려 운동","국채 보상 운동","형평 운동"],"a":1,"e":"근면, 자조, 협동을 구호로 농촌 근대화를 추진한 것은 1970년대 새마을 운동이다.","sec":9},{"id":"kh-q255","set":"현대","n":16,"s":1,"q":"[자료] 1972년 박정희 정부는 대통령에게 강력한 권한을 부여하는 헌법을 제정하였다. 대통령은 통일 주체 국민 회의에서 선출되고 국회의원 일부를 임명할 수 있었다.\n\n밑줄 그은 헌법이 시행된 시기의 사실로 옳은 것은?","o":["부마 민주 항쟁이 일어났다.","4.19 혁명이 일어났다.","발췌 개헌이 이루어졌다.","제헌 헌법이 공포되었다.","6.25 전쟁이 발발하였다."],"a":1,"e":"유신 헌법 체제(1972~1979)에 대한 저항으로 1979년 부마 민주 항쟁이 일어났다. 나머지는 유신 이전의 사실이다.","sec":9},{"id":"kh-q256","set":"현대","n":17,"s":1,"q":"[자료] 1980년 신군부의 집권과 계엄 확대에 맞서 광주 시민과 학생들이 민주화를 요구하며 저항하였다. 계엄군의 무력 진압으로 많은 희생자가 발생하였다.\n\n밑줄 그은 사건으로 옳은 것은?","o":["5.18 민주화 운동","6월 민주 항쟁","4.19 혁명","부마 민주 항쟁","6.3 시위"],"a":1,"e":"1980년 신군부에 맞서 광주에서 일어난 민주화 운동은 5.18 민주화 운동이다.","sec":9},{"id":"kh-q257","set":"현대","n":18,"s":1,"q":"[자료] 1987년 전국적인 민주화 시위가 일어나자 여당 대통령 후보는 대통령 직선제 개헌 등을 수용하는 선언을 발표하였다.\n\n밑줄 그은 선언으로 옳은 것은?","o":["6.29 선언","7.4 남북 공동 성명","6.15 남북 공동 선언","10월 유신 선언","3.1 독립 선언"],"a":1,"e":"6월 민주 항쟁의 결과 노태우가 대통령 직선제 개헌을 수용한 것은 6.29 선언이다.","sec":9},{"id":"kh-q258","set":"현대","n":19,"s":1,"q":"남북 관계 관련 합의를 발표된 순서대로 옳게 나열한 것은? (가) 7.4 남북 공동 성명 (나) 남북 기본 합의서 (다) 6.15 남북 공동 선언","o":["(가)-(나)-(다)","(가)-(다)-(나)","(나)-(가)-(다)","(다)-(나)-(가)","(나)-(다)-(가)"],"a":1,"e":"7.4 남북 공동 성명(1972), 남북 기본 합의서(1991), 6.15 남북 공동 선언(2000) 순서이다.","sec":9},{"id":"kh-q259","set":"현대","n":20,"s":1,"q":"[자료] 2000년 분단 이후 처음으로 남북 정상이 평양에서 만나 회담을 열고 통일 문제를 자주적으로 해결하기로 하는 등 합의를 담은 이 선언을 발표하였다.\n\n밑줄 그은 선언에 해당하는 정부로 옳은 것은?","o":["김대중 정부","박정희 정부","전두환 정부","이승만 정부","노태우 정부"],"a":1,"e":"2000년 최초의 남북 정상 회담과 6.15 남북 공동 선언은 김대중 정부 시기의 일이다.","sec":9},{"id":"kh-q260","set":"현대","n":21,"s":1,"q":"[자료] 1997년 외환 부족으로 국가 부도 위기에 처하자 정부는 국제 통화 기금(IMF)에 구제 금융을 요청하였다. 이를 극복하기 위해 국민들은 금 모으기 운동을 전개하였다.\n\n밑줄 그은 위기를 극복하기 위한 노력으로 옳은 것은?","o":["국민들이 금 모으기 운동을 전개하였다.","경제 개발 5개년 계획을 처음 수립하였다.","농지 개혁법을 제정하였다.","산미 증식 계획을 추진하였다.","화폐 정리 사업을 실시하였다."],"a":1,"e":"1997년 외환 위기를 극복하기 위해 국민들은 금 모으기 운동을 전개하였다. 나머지는 시기가 맞지 않는 사실이다.","sec":9},{"id":"kh-g77-1","set":"제77회 기출","n":1,"s":1,"q":"[자료] [여주 흔암리 유적 체험 프로그램 안내] 사유 재산과 계급이 발생한 이 시대의 대표적 유적지인 여주 흔암리 유적을 주제로 한 체험. 주요 프로그램: 민무늬 토기 조각 맞추기 / 반달 돌칼로 벼 이삭 수확하기 / 흙 속 탄화미 찾아보기.\n\n밑줄 그은 '이 시대'의 생활 모습으로 가장 적절한 것은?","o":["철제 무기로 정복 활동을 벌였다.","소를 이용한 깊이갈이가 일반화되었다.","많은 인력을 동원하여 고인돌을 축조하였다.","주먹도끼, 찍개 등의 뗀석기를 처음 제작하였다.","가락바퀴와 뼈바늘을 이용하여 옷을 만들기 시작하였다."],"a":3,"e":"민무늬 토기·반달 돌칼·탄화미·계급 발생은 청동기 시대이다. 청동기에는 많은 인력을 동원해 고인돌을 축조하였다. ①⑤는 철기·신석기, ②는 조선 후기, ④는 구석기.","sec":0},{"id":"kh-g77-2","set":"제77회 기출","n":2,"s":1,"q":"[자료] [역사 신문] 한의 사신 섭하가 (가)의 비왕 장을 살해하는 외교적 사건 발생. 한 무제가 섭하에게 벼슬을 내리자 우거왕이 분노하여 섭하를 죽였고, 이에 한 무제가 병력을 모아 (가)을/를 침공하였다.\n\n(가) 나라에 대한 설명으로 옳은 것은?","o":["민며느리제라는 혼인 풍습이 있었다.","국가 중대사를 정사암에서 논의하였다.","여러 가(加)들이 별도로 사출도를 주관하였다.","지방의 여러 성에 욕살, 처려근지 등을 두었다.","사회 질서를 유지하기 위해 범금 8조를 만들었다."],"a":5,"e":"우거왕·한 무제의 침공 대상은 (위만)고조선이다. 고조선은 사회 질서 유지를 위해 범금 8조(8조법)를 두었다. ①옥저 ②백제 ③부여 ④고구려.","sec":1},{"id":"kh-g77-3","set":"제77회 기출","n":3,"s":1,"q":"[자료] 『삼국지』위서 동이전에 기록된 이 나라의 특징: 특산물로 단궁·과하마·반어피가 유명하였다. 10월에 제천 행사인 무천이 있었다. 호랑이를 신으로 여겨 제사를 지냈다.\n\n밑줄 그은 '이 나라'에 대한 탐구 활동으로 가장 적절한 것은?","o":["진대법의 시행 목적을 파악한다.","책화의 사회적 의미를 조사한다.","신성 구역인 소도의 기능을 알아본다.","화백 회의의 의사 결정 방식을 살펴본다.","포상 8국 전쟁이 전개되는 과정을 찾아본다."],"a":2,"e":"단궁·과하마·반어피·무천은 동예이다. 동예에는 읍락 경계를 침범하면 배상하는 책화가 있었다. ①고구려 ③삼한 ④신라 ⑤가야.","sec":1},{"id":"kh-g77-5","set":"제77회 기출","n":5,"s":1,"q":"[자료] [모둠 발표 대화] 백가의 난을 평정하고 왕권을 강화하였음 / 중국 남조의 양에 '고구려를 여러 차례 격파하고 다시 강국이 되었다'는 국서를 보냄 / 1971년 발굴된 이 왕의 무덤에서 왕과 왕비의 지석, 석수 등이 출토됨.\n\n다음 대화에 나타난 왕에 대한 설명으로 옳은 것은?","o":["금마저에 미륵사를 창건하였다.","고흥에게 서기를 편찬하게 하였다.","지방의 22담로에 왕족을 파견하였다.","동진에서 온 마라난타를 통해 불교를 수용하였다.","장군 달기를 보내 고구려의 도살성을 점령하였다."],"a":3,"e":"무령왕릉(1971 발굴)·지석·백가의 난 평정은 백제 무령왕이다. 무령왕은 지방 22담로에 왕족을 파견해 지방을 통제하였다. ①무왕 ②근초고왕 ④침류왕.","sec":2},{"id":"kh-g77-6","set":"제77회 기출","n":6,"s":1,"q":"[자료] (가) 왕이 태자 김법민을 보내 병선 100척으로 덕물도에서 소정방을 맞이하게 함(백제 남쪽에서 대왕 군대와 만나 도성을 깨뜨리려 함). (나) 사찬 시득이 수군을 이끌고 소부리주 기벌포에서 설인귀와 싸워 크고 작게 22번 이김.\n\n(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?","o":["을지문덕이 살수에서 대승을 거두었다.","복신과 도침이 부여풍을 왕으로 추대하였다.","윤충이 군사를 이끌고 대야성을 함락시켰다.","연개소문이 정변을 일으켜 영류왕을 시해하였다.","김춘추가 당으로 건너가 군사 연합을 성사시켰다."],"a":2,"e":"(가)는 660년 백제 공격 직전, (나)는 676년 기벌포 전투이다. 그 사이 백제 부흥 운동으로 복신·도침이 부여풍을 왕으로 추대하였다. ①612 ③642 ④642 ⑤648.","sec":3},{"id":"kh-g77-7","set":"제77회 기출","n":7,"s":1,"q":"[자료] 영역은 사방 5천 리이며 5경과 15부를 두었다. 서쪽으로 중국과 통하고 남쪽으로 신라와 교빙하고 북쪽으로 거란에 맞서고 동쪽으로 일본에 사신을 보내어 동북의 안쪽 지역을 압도하며 거의 3백 년 동안 존속하였다. - 『해동역사』\n\n다음 자료에 해당하는 국가에 대한 설명으로 옳은 것은?","o":["12월에 영고라는 제천 행사를 열었다.","주자감을 설치하여 인재를 양성하였다.","군사 조직으로 9서당 10정을 편성하였다.","기인 제도를 실시하여 지방 세력을 견제하였다.","왕족인 부여씨와 8성 귀족이 지배층을 이루었다."],"a":2,"e":"5경 15부·해동성국은 발해이다. 발해는 국립 교육 기관으로 주자감을 두었다. ①부여 ③통일신라 ④고려 ⑤백제.","sec":3},{"id":"kh-g77-8","set":"제77회 기출","n":8,"s":1,"q":"[자료] [대화형 AI] 사진 속 무덤은 (가)의 왕릉으로 추정되는 천추총이다. (가)의 도성이었던 국내성 지역에 위치하며 대형 계단식 돌무지무덤이고, 주변에서 '영락'으로 판독되는 명문 기와 조각도 발견되었다.\n\n(가) 국가의 경제 상황으로 가장 적절한 것은?","o":["수도에 서시와 남시를 설치하였다.","활구라고 불리는 은병을 주조하였다.","집집마다 부경이라는 창고가 있었다.","관료전을 지급하고 녹읍을 폐지하였다.","풍흉에 따라 9등급으로 전세를 거두었다."],"a":3,"e":"국내성·계단식 돌무지무덤·영락 연호는 고구려이다. 고구려는 집집마다 부경이라는 창고를 두었다. ①통일신라 ②고려 ④통일신라 ⑤조선(공법).","sec":2},{"id":"kh-g77-9","set":"제77회 기출","n":9,"s":1,"q":"[자료] ○ (가)이/가 나주의 상황을 근심하여 왕건에게 가서 지키도록 명령하고 해군대장군으로 삼음. ○ (가)은/는 백성을 지푸라기처럼 여기고 참위설을 믿어 송악을 버리고 부양(현 철원 북부)으로 돌아가 궁궐을 세우니 백성이 공사에 시달림.\n\n(가) 인물에 대한 설명으로 옳은 것은?","o":["안승을 보덕왕으로 봉하였다.","광평성 등의 정치 기구를 마련하였다.","외교 담판으로 강동 6주를 확보하였다.","김부를 경주의 사심관으로 임명하였다.","신라를 공격하여 경애왕을 죽게 하였다."],"a":2,"e":"철원 천도·참위설은 후고구려의 궁예이다. 궁예는 광평성 등 정치 기구를 마련하였다. ①신라 문무왕 ③서희 ④왕건 ⑤견훤.","sec":3},{"id":"kh-g77-10","set":"제77회 기출","n":10,"s":1,"q":"[자료] [가상 뉴스] 청해진이 폐지되고 주민들이 벽골군으로 옮겨진다는 소식. 해상 무역 거점이던 청해진이 장보고의 건의로 설치된 지 20여 년 만의 일이다.\n\n다음 가상 뉴스에서 보도한 내용이 있었던 시기에 볼 수 있는 모습으로 가장 적절한 것은?","o":["계백료서를 읽고 있는 관리","담배를 밭에 심고 있는 농민","조위총의 난을 진압하는 군인","진전사에서 참선하는 선종 승려","낙랑군과 교역할 덩이쇠를 주조하는 장인"],"a":4,"e":"청해진 폐지(851)는 신라 하대이다. 신라 하대에는 선종이 유행하여 진전사 등에서 참선하는 승려를 볼 수 있었다. ①고려 초 ②조선 후기 ③고려 무신기 ⑤삼한/가야.","sec":3},{"id":"kh-g77-11","set":"제77회 기출","n":11,"s":1,"q":"[자료] [현화사비 탁본] 앞면에는 송의 연호 천희, 뒷면에는 (가)의 연호 태평이 새겨져 있다. 고려는 귀주 대첩에서 (가)을/를 격퇴하였지만 조공 책봉 관계를 수용하며 실리와 안정을 추구하였다.\n\n(가) 국가에 대한 고려의 대응으로 옳은 것은?","o":["별무반을 편성하였다.","화통도감을 설치하였다.","진관 체제를 실시하였다.","초조대장경을 조판하였다.","동녕부의 반환을 요청하였다."],"a":4,"e":"귀주 대첩의 상대인 (가)는 거란이다. 고려는 거란 침입을 물리치려는 염원으로 초조대장경을 조판하였다. ①여진 ②왜구(고려말) ③조선 ⑤원.","sec":4},{"id":"kh-g77-12","set":"제77회 기출","n":12,"s":1,"q":"[자료] [다큐 기획안: 우리 역사 속 생태·환경] 1부 혜공왕 대 재이 발생과 백좌법회 / 2부 (가) / 3부 『승정원일기』로 본 소빙기 농업과 경신대기근 / 4부 해수구제 사업과 한반도 호랑이 사냥. (구성은 시대 순)\n\n(가)에 들어갈 내용으로 가장 적절한 것은?","o":["응방의 설치와 매 서식지의 변화","시화호의 조성과 갯벌 생태계 파괴","수의 침략과 요하 일대 감염병의 유행","가죽 제품 수요 증가와 독도 강치의 멸종","을축년 대홍수의 피해와 경성부의 대응 양상"],"a":1,"e":"1부(신라 하대)와 3부(조선 후기 경신대기근) 사이 시대는 고려이다. 원 간섭기 고려에는 매를 사육·공납하던 응방이 설치되었다. ②현대 ③삼국 ④일제 ⑤일제.","sec":4},{"id":"kh-g77-14","set":"제77회 기출","n":14,"s":1,"q":"[자료] [한국사 탐구 계획서] 참고 자료 - 태조 왕건 청동상(통천관을 쓰고 있음) / 청주 용두사지 철당간(준풍이라는 연호가 새겨져 있음).\n\n(가) 탐구 주제로 가장 적절한 것은?","o":["신해통공의 단행 배경","명의 멸망과 소중화주의의 대두","골품제가 일상생활에 끼친 영향","울산항을 통한 아라비아 상인들과의 교류","황제국 표방 사례를 통해 본 외왕내제 의식"],"a":5,"e":"통천관(황제의 관)·준풍 등 독자 연호는 고려의 황제국 표방(외왕내제)을 보여 준다. ①조선 후기 ②조선 후기 ③통일신라 ④통일신라.","sec":4},{"id":"kh-g77-15","set":"제77회 기출","n":15,"s":1,"q":"[자료] [초상화로 보는 한국사] 소수 서원에 봉안된 인물의 초상화. 그는 충렬왕 때 원에 갔다가 주희의 저서를 들여오며 성리학을 본격 소개하였다. 충숙왕이 그의 초상화를 문묘에 모시게 하였다.\n\n밑줄 그은 '인물'이 활동한 시기에 볼 수 있는 모습으로 가장 적절한 것은?","o":["제왕운기를 읽고 있는 왕","만동묘 복구를 건의하는 유생","동몽선습을 공부하는 서당 학동","독서삼품과 시행을 준비하는 관리","주자소에서 계미자를 주조하는 장인"],"a":1,"e":"성리학을 처음 소개한 인물은 안향(고려 후기)이다. 이 시기 이승휴가 제왕운기를 저술하였다. ②조선 후기 ③조선 ④통일신라 ⑤조선 태종.","sec":4},{"id":"kh-g77-16","set":"제77회 기출","n":16,"s":1,"q":"[자료] [교외 체험 학습 보고서 - 강화 석릉] 강화 석릉은 고려 희종의 무덤이다. 이의민을 제거하고 집권한 (가)이/가 스스로 교정별감이 되어 전횡하자 희종이 암살하려 했으나 도방의 방해로 실패, 희종은 강화도로 유배됨.\n\n(가) 인물에 대한 설명으로 옳은 것은?","o":["비담과 염종의 반란을 진압하였다.","만권당에서 원의 학자들과 교유하였다.","인사 행정을 담당하던 정방을 폐지하였다.","봉사 10조를 올려 시정 개혁을 건의하였다.","오월에 사신을 보내고 검교태보의 직을 받았다."],"a":4,"e":"이의민을 제거하고 교정별감이 된 인물은 최충헌이다. 최충헌은 봉사 10조를 올려 시정 개혁을 건의하였다. ①신라 김유신 ②이제현 ③공민왕 ⑤견훤.","sec":4},{"id":"kh-g77-17","set":"제77회 기출","n":17,"s":1,"q":"[자료] (가) '삼국의 역사를 기전체로 정리한 삼국사기의 편찬을 총괄하였소.' / (나) '불교 중심의 설화와 단군의 건국 이야기 등을 담은 삼국유사를 저술하였소.'\n\n(가), (나) 인물에 대한 설명으로 옳은 것은?","o":["(가) - 관군을 이끌고 묘청의 난을 진압하였다.","(가) - 시무 28조를 올려 국가 운영 방안을 제시하였다.","(나) - 법화 신앙을 바탕으로 백련 결사를 이끌었다.","(나) - 화폐 발행을 위해 주전도감 설치를 건의하였다.","(가), (나) - 심성 도야를 강조하고 유불 일치설을 주장하였다."],"a":1,"e":"(가)는 삼국사기의 김부식, (나)는 삼국유사의 일연이다. 김부식은 묘청의 난을 진압하였다. ②최승로 ③요세 ④의천 ⑤지눌.","sec":4},{"id":"kh-g77-18","set":"제77회 기출","n":18,"s":1,"q":"[자료] 위화도에서 좌·우군도통사가 회군을 요청하니 최영이 거절함. 원의 잔당(북원)과 협공을 약속하고 요동을 협공하려 하였으나 좌·우군도통사가 거듭 회군을 요청함. - 『고려사』 [연표] 1009 강조의 정변-(가)-1126 이자겸의 난-(나)-1232 처인성 전투-(다)-1273 삼별초 항쟁 진압-(라)-1351 공민왕 즉위-(마)-1392 고려 멸망\n\n다음 상황이 나타난 시기를 연표에서 옳게 고른 것은?","o":["(가)","(나)","(다)","(라)","(마)"],"a":5,"e":"위화도 회군은 1388년으로, 공민왕 즉위(1351)와 고려 멸망(1392) 사이인 (마) 시기에 해당한다.","sec":4},{"id":"kh-g77-19","set":"제77회 기출","n":19,"s":1,"q":"[자료] ○ 문하부 좌우 정승을 의정부 좌우 정승으로 고치고 … 문하부의 이름을 혁파하고 낭사(郎舍)를 고쳐 (가)(으)로 하였다. ○ (가)의 대사간 성현 등이 상소하였다.\n\n(가) 기구에 대한 설명으로 옳은 것은?","o":["사헌부, 홍문관과 함께 3사로 불렸다.","국왕 직속 사법 기구로 반역죄 등을 다루었다.","사초와 시정기를 바탕으로 실록을 편찬하였다.","왕의 비서 기관으로 왕명의 출납을 관장하였다.","사대교린에 관한 문서를 관장하기 위해 설치되었다."],"a":1,"e":"문하부 낭사를 계승하고 대사간을 둔 (가)는 사간원이다. 사간원은 사헌부·홍문관과 함께 3사로 불렸다. ②의금부 ③춘추관 ④승정원 ⑤예조/승문원.","sec":5},{"id":"kh-g77-20","set":"제77회 기출","n":20,"s":1,"q":"[자료] [이달의 책 - 대불정수능엄경(언해)] 중국 승려 계환의 주해에 (가)이/가 훈민정음으로 구결을 달고 한계희·김수온 등이 번역·편찬. 목판본은 (가)이/가 만든 간경도감에서 간행한 최초의 불경 언해서이다.\n\n(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?","o":["조의제문을 빌미로 무오사화가 일어났다.","세계 지도인 혼일강리역대국도지도가 제작되었다.","예악 질서 확립을 위한 악학궤범이 완성되었다.","역대 문물 제도를 정리한 동국문헌비고가 편찬되었다.","현직 관리에게만 수조권을 지급하는 직전법이 시행되었다."],"a":5,"e":"간경도감을 세운 왕은 세조이다. 세조는 현직 관리에게만 수조권을 주는 직전법을 시행하였다. ①연산군 ②태종 ③성종 ④영조.","sec":5},{"id":"kh-g77-21","set":"제77회 기출","n":21,"s":1,"q":"[자료] 이곳은 안동의 병산 서원으로 (가)의 위패가 봉안되어 있다. (가)은/는 훈련도감 설치를 건의하고 공납의 폐단을 시정하고자 대공수미법을 제안하였다.\n\n(가) 인물에 대한 설명으로 옳은 것은?","o":["기대승과 사단칠정 논쟁을 전개하였다.","소학의 보급과 현량과 실시를 주장하였다.","기축봉사를 올려 명에 대한 의리를 내세웠다.","임진왜란의 상황 등을 담은 징비록을 저술하였다.","최초로 100리 척을 사용하여 동국지도를 제작하였다."],"a":4,"e":"병산 서원 배향·훈련도감 건의·대공수미법은 유성룡이다. 유성룡은 임진왜란을 기록한 징비록을 저술하였다. ①이황 ②조광조 ③송시열 ⑤정상기.","sec":5},{"id":"kh-g77-22","set":"제77회 기출","n":22,"s":1,"q":"[자료] [시나리오 #11 남한산성 안] 임금이 칸(汗)의 항복 요구 서신을 읽은 뒤 대신들과 논의. 김상헌은 항전을, 최명길은 화의를 주장하고, 임금은 성을 굳게 지키며 회답하려 함.\n\n다음 시나리오의 상황 이후에 전개된 사실로 옳은 것은?","o":["강홍립 부대가 사르후 전투에 참전하였다.","김종서가 두만강 일대에 6진을 개척하였다.","김시민이 진주성 전투에서 크게 승리하였다.","이종무가 왜구의 근거지인 쓰시마섬을 정벌하였다.","이완이 어영대장으로 임명되어 북벌을 준비하였다."],"a":5,"e":"남한산성·칸의 항복 요구는 병자호란(1636)이다. 이후 효종 대 이완이 어영대장이 되어 북벌을 준비하였다. ①광해군 ②세종 ③임진왜란 ④세종.","sec":5},{"id":"kh-g77-23","set":"제77회 기출","n":23,"s":1,"q":"[자료] [변박 특별전 - 왜관도] 변박이 그린 초량 왜관의 전경으로 관수가를 중심으로 서관·동관이 나뉘고 50여 개 건물 명칭이 표기됨. 초량 왜관에서 대일 무역이 이루어지던 시기의 왜관 구성과 규모를 알 수 있다.\n\n밑줄 그은 '시기'에 볼 수 있는 모습으로 적절하지 않은 것은?","o":["계해약조의 초안을 작성하는 관리","까치를 소재로 민화를 그리는 화원","세책가에서 춘향전을 빌리는 부녀자","시사(詩社)를 조직하여 활동하는 서리","송파장에서 산대놀이를 공연하는 광대"],"a":1,"e":"초량 왜관 시기는 조선 후기이다. 계해약조는 조선 전기(세종, 1443)의 일이므로 적절하지 않다. ②③④⑤는 모두 조선 후기의 모습.","sec":6},{"id":"kh-g77-24","set":"제77회 기출","n":24,"s":1,"q":"[자료] [이십공신회맹축 - 보사공신녹훈후] 보사 공신(경신환국의 공신)이 기사환국·갑술환국을 거치며 공신 지위를 박탈당했다가 회복하는 정황이 반영되어, (가) 재위 시기의 급변하는 정치 상황을 파악하는 데 도움을 줌.\n\n(가) 왕이 추진한 정책으로 옳은 것은?","o":["문신을 재교육하기 위한 초계문신제를 실시하였다.","각 궁방과 중앙 관서의 공노비 6만여 명을 해방하였다.","국왕의 호위와 수도 방어를 위해 금위영을 창설하였다.","각지의 농법을 작물별로 정리한 농사직설을 편찬하였다.","붕당 정치의 폐해를 경계하기 위해 탕평비를 건립하였다."],"a":3,"e":"경신·기사·갑술환국은 숙종 대의 일이다. 숙종은 금위영을 창설하여 5군영 체제를 완성하였다. ①정조 ②순조 ④세종 ⑤영조.","sec":6},{"id":"kh-g77-25","set":"제77회 기출","n":25,"s":1,"q":"[자료] 근래 듣건대 도고라는 방식이 새로 나와 한 사람이 물품을 독차지하면서 다른 사람은 개별적으로 살 수 없게 되었다고 한다. … 이익은 한 사람에게 돌아가고 피해는 만민이 받는다. … 한성부와 평시서가 엄히 금단하여 도고를 없애도록 하소서.\n\n다음 자료에 나타난 시기의 경제 상황으로 옳은 것은?","o":["관리에게 전지와 시지가 지급되었다.","솔빈부의 말이 특산품으로 수출되었다.","관청에 물품을 조달하는 공인이 활동하였다.","당항성, 영암이 국제 무역항으로 번성하였다.","삼한통보, 해동통보 등의 화폐가 발행되었다."],"a":3,"e":"도고(독점 상업)는 조선 후기의 현상이다. 이 시기 대동법 시행으로 관청에 물품을 조달하는 공인이 활동하였다. ①고려(전시과) ②발해 ④통일신라 ⑤고려.","sec":6},{"id":"kh-g77-26","set":"제77회 기출","n":26,"s":1,"q":"[자료] [신문] 『북학의』친필 고본이 보물로 지정. (가)이/가 청의 연경에 다녀온 후 국가 제도·정책 등의 개혁 필요성과 실천 방안을 제시한 책으로, 박지원의 친필 서문이 함께 남아 있다.\n\n(가) 인물에 대한 설명으로 옳은 것은?","o":["양명학을 연구하여 강화학파를 형성하였다.","기기도설을 참고하여 거중기를 설계하였다.","역대 명필을 연구하여 추사체를 창안하였다.","규장각 검서관으로 무예도보통지 편찬에 참여하였다.","지부복궐척화의소를 올려 왜양일체론을 주장하였다."],"a":4,"e":"『북학의』의 저자는 박제가이다. 박제가는 서얼 출신으로 규장각 검서관이 되어 무예도보통지 편찬에 참여하였다. ①정제두 ②정약용 ③김정희 ⑤최익현.","sec":6},{"id":"kh-g77-27","set":"제77회 기출","n":27,"s":1,"q":"[자료] [답사 안내: 고구려비를 품은 (가)의 역사를 걷다] 답사 경로 - 탑평리 칠층 석탑(중앙탑) → 탄금대 → 임충민공 충렬사 → 미륵 대원지.\n\n(가) 지역에 대한 탐구 활동으로 가장 적절한 것은?","o":["이괄이 반란을 일으킨 근거지를 알아본다.","김정희가 세한도를 그린 유배지를 검색한다.","정약전이 자산어보를 저술한 곳을 조사한다.","강주룡이 고공 농성을 벌인 을밀대의 위치를 찾아본다.","김윤후가 노비 등을 이끌고 몽골군을 격퇴한 장소를 파악한다."],"a":5,"e":"중앙탑·탄금대·충주 고구려비가 있는 (가)는 충주이다. 충주성에서 김윤후가 노비 등을 이끌고 몽골군을 격퇴하였다. ①이괄-공주/한양 ②제주 ③흑산도 ④평양.","sec":4},{"id":"kh-g77-28","set":"제77회 기출","n":28,"s":1,"q":"[자료] 진주 안핵사 박규수가 상소: '난민들이 스스로 죄에 빠진 데는 이유가 있으니, 살을 베고 뼈를 깎는 고통은 환곡과 향곡이 으뜸입니다. 진주에서 허위로 부과한 세금은 이미 조사 결과를 아뢰었습니다. …'\n\n다음 자료에 나타난 상황 이후의 사실로 옳은 것은?","o":["홍경래 등이 봉기하여 정주성을 점령하였다.","신돈이 중심이 되어 전민변정 사업을 운영하였다.","삼정의 문란을 시정하고자 삼정이정청이 설치되었다.","기금의 이자로 빈민을 구휼하는 제위보가 만들어졌다.","황사영이 외국 군대의 출병을 요청하는 백서를 작성하였다."],"a":3,"e":"진주 안핵사 박규수는 임술 농민 봉기(1862) 관련이다. 이후 삼정의 문란을 시정하고자 삼정이정청이 설치되었다. ①1811 ②고려 ④고려 ⑤1801.","sec":6},{"id":"kh-g77-29","set":"제77회 기출","n":29,"s":1,"q":"[자료] 적들이 성벽 아래에 당도하자 우리 군사가 일제히 총을 쏘아 물리침. 양헌수가 순무영에 승전보를 띄움: '오늘 적병이 정족산성을 침범하였으나 우리 군사가 일제히 사격하여 물리쳤습니다.'\n\n다음 자료에 나타난 사건의 배경으로 가장 적절한 것은?","o":["운요호가 강화도와 영종도를 공격하였다.","오페르트가 남연군 묘 도굴을 시도하였다.","교조 신원을 요구하는 보은 집회가 열렸다.","병인박해로 천주교 신부와 신자들이 처형되었다.","김홍집이 가지고 온 조선책략이 조선에 유포되었다."],"a":4,"e":"양헌수·정족산성 전투는 병인양요(1866)이다. 병인양요의 배경은 프랑스 선교사·신자를 처형한 병인박해이다. ①1875 ②1868 ③1893 ⑤1880.","sec":7},{"id":"kh-g77-30","set":"제77회 기출","n":30,"s":1,"q":"[자료] [관보 제214호] 내부 고시는 이 개혁에 따라 시행된 단발령을 알리는 내용으로 국왕이 먼저 단발함. 관보의 연호 '건양'은 국모 시해 사건 이후 추진된 이 개혁의 일환으로 태양력이 도입되면서 새로 정한 것이다.\n\n밑줄 그은 '이 개혁'의 내용으로 옳은 것은?","o":["박문국을 두어 한성순보를 발행하였다.","근대식 무기 제조 시설인 기기창을 설립하였다.","군제를 개편하여 친위대와 진위대를 설치하였다.","공사 노비법을 혁파하고 과부의 재가를 허용하였다.","비변사를 혁파하여 의정부와 삼군부의 기능을 회복하였다."],"a":3,"e":"단발령·건양 연호·태양력은 을미개혁(1895)이다. 을미개혁으로 군제를 개편해 친위대·진위대를 설치하였다. ①②1880년대 ④갑오개혁 ⑤흥선대원군.","sec":7},{"id":"kh-g77-31","set":"제77회 기출","n":31,"s":1,"q":"[자료] 이 사진은 묄렌도르프의 집으로, 본래 선혜청 당상 민겸호의 집이었으나 그가 (가) 때 피살되자 고종이 하사한 것이다. (가)을/를 진압한 청의 추천으로 조선 외교 고문이 된 묄렌도르프가 서양식으로 개축하였다.\n\n(가) 사건에 대한 설명으로 옳은 것은?","o":["김옥균 등 개화파가 주도하였다.","제물포 조약이 체결되는 계기가 되었다.","전개 과정에서 홍범 14조가 반포되었다.","통리기무아문이 설치되는 배경이 되었다.","외규장각 도서가 약탈되는 결과를 가져왔다."],"a":2,"e":"민겸호 피살·청군 진압은 임오군란(1882)이다. 임오군란의 결과 일본과 제물포 조약이 체결되었다. ①갑신정변 ③갑오개혁 ④개항 직후 ⑤병인양요.","sec":7},{"id":"kh-g77-32","set":"제77회 기출","n":32,"s":1,"q":"[자료] [포와유람기] 현순이 이 지역의 호놀룰루 등에서 체류한 경험을 바탕으로 쓴 견문록. 20세기 초 사탕수수 농장에 도착한 초기 한인 이민자의 생활과, 포와(布哇)라 불린 이 지역의 지리·역사·문화가 기록됨.\n\n밑줄 그은 '이 지역'에서 전개된 민족 운동에 대한 설명으로 옳은 것은?","o":["한인 자치 기구인 경학사를 조직하였다.","한인 교육을 위해 박달 학원을 설립하였다.","무장 투쟁을 위해 대조선 국민 군단을 결성하였다.","유학생을 중심으로 2·8 독립 선언서를 발표하였다.","대한 광복군 정부를 중심으로 무장 독립 투쟁을 준비하였다."],"a":3,"e":"포와(호놀룰루)는 하와이이다. 박용만은 하와이에서 대조선 국민 군단을 결성해 무장 투쟁을 준비하였다. ①서간도 ②북간도 ④일본 도쿄 ⑤연해주.","sec":8},{"id":"kh-g77-33","set":"제77회 기출","n":33,"s":1,"q":"[자료] [한국사 교실 수행 과제 - 조약 관련 자료] 중명전(조약이 강제 체결된 장소) / 민영환(조약 체결에 항거하여 유서를 남기고 자결) / 자신회(나철·오기호 등이 조약에 찬성한 다섯 대신을 처단하려 조직).\n\n다음 자료에 나타난 조약에 대한 설명으로 옳은 것은?","o":["청의 알선으로 체결이 추진되었다.","통감부가 설치되는 결과를 가져왔다.","천주교 포교를 허용하는 근거가 되었다.","스티븐스가 외교 고문으로 부임하는 계기가 되었다.","대한 제국 군대의 해산을 규정하는 내용이 포함되어 있다."],"a":2,"e":"중명전·민영환·을사오적 처단은 을사늑약(1905)이다. 을사늑약으로 통감부가 설치되었다. ①조미수호통상조약 ③조프수호통상조약 ④제1차 한일협약 ⑤정미7조약.","sec":7},{"id":"kh-g77-34","set":"제77회 기출","n":34,"s":1,"q":"[자료] [특별전: 국외 독립운동의 숨은 주역, 안태국] (가)에서 운영한 태극 서관의 주임 등을 맡은 안태국. 그는 안창호·양기탁 등을 중심으로 비밀리에 결성된 (가)에서 국외 독립군 기지 건설을 위해 군자금 모금·이주민 모집에 힘씀.\n\n(가) 단체에 대한 설명으로 옳은 것은?","o":["만세보를 발행하였다.","대성 학교를 설립하였다.","만민 공동회를 개최하였다.","부민관 폭파 의거를 계획하였다.","일제의 황무지 개간권 요구를 저지하였다."],"a":2,"e":"안창호·양기탁·태극 서관·비밀 결사는 신민회이다. 신민회는 대성 학교를 세워 민족 교육에 힘썼다. ①천도교 ③독립협회 ④대한애국청년당 ⑤보안회.","sec":7},{"id":"kh-g77-35","set":"제77회 기출","n":35,"s":1,"q":"[자료] [근대 교육의 도입] 영어·산학·지리 등을 주요 과목으로 개설한 이 학교의 교과서. '사민필지'는 미국인 헐버트가 이 학교의 교사 시절 한글로 지은 세계 지리서이다.\n\n밑줄 그은 '이 학교'에 대한 설명으로 옳은 것은?","o":["7재라는 전문 강좌가 있었다.","덕원부 관민이 합심하여 만들었다.","교육입국 조서에 근거하여 세워졌다.","주요 건물로 대성전과 명륜당을 두었다.","좌원과 우원을 구분하여 학생을 선발하였다."],"a":5,"e":"헐버트·사민필지·영어·산학은 육영공원(1886)이다. 육영공원은 좌원·우원으로 나누어 학생을 선발하였다. ①고려 국자감 ②원산학사 ③한성사범학교 ④성균관/향교.","sec":7},{"id":"kh-g77-36","set":"제77회 기출","n":36,"s":1,"q":"[자료] [대화] 나석주 의사가 조선 식산 은행과 동양 척식 주식회사에 폭탄을 던진 사건 기사. 나석주는 일제의 기관 파괴·요인 암살을 목적으로 조직된 이 단체의 단원으로, 경제 수탈의 상징인 두 기관에 폭탄을 투척함.\n\n밑줄 그은 '이 단체'에 대한 설명으로 옳은 것은?","o":["고종의 강제 퇴위에 반대하는 시위를 주도하였다.","조선 총독부에 국권 반환 요구서를 제출하려 하였다.","독립운동 자금 마련을 위해 독립 공채를 발행하였다.","신채호가 쓴 조선 혁명 선언을 활동 지침으로 삼았다.","신규식을 중심으로 조직되어 교민들의 단결을 도모하였다."],"a":4,"e":"나석주가 소속된 단체는 의열단이다. 의열단은 신채호가 쓴 조선 혁명 선언을 활동 지침으로 삼았다. ①대한자강회 ②독립의군부 ③임시정부 ⑤동제사.","sec":8},{"id":"kh-g77-37","set":"제77회 기출","n":37,"s":1,"q":"[자료] [사진과 함께하는 역사 - 임시 토지 조사국] 임시 토지 조사국은 일제가 식민 지배의 경제적 기반 마련을 목적으로 이 정책을 추진하며 설치한 기구로, 토지 조사·측량, 지적도와 토지 대장 작성을 수행하였다.\n\n밑줄 그은 '이 정책'이 실시된 시기에 볼 수 있는 모습으로 가장 적절한 것은?","o":["태형을 집행하는 헌병 경찰","원수부에서 업무를 처리하는 관리","몸뻬 착용을 홍보하는 애국반 반장","경인선 개통식에 참석하는 일본인 거류민","나운규가 감독한 아리랑의 첫 상영을 준비하는 단성사 직원"],"a":1,"e":"임시 토지 조사국·토지 조사 사업은 1910년대 무단 통치기이다. 이 시기에는 태형을 집행하는 헌병 경찰을 볼 수 있었다. ②대한제국 ③1930~40년대 ④1899 ⑤1926.","sec":8},{"id":"kh-g77-38","set":"제77회 기출","n":38,"s":1,"q":"[자료] 조선인 운동을 민족 단일당으로 결집하고자 (가)이/가 조직됨. 각지에 지회가 설치되었고, (가)은/는 민중 대회를 준비하다 발각되어 타격을 입은 뒤 '해소'라는 기록을 남기고 5년간의 자취를 청산하였다.\n\n(가) 단체의 활동으로 옳은 것은?","o":["개벽, 신여성 등의 잡지를 발행하였다.","중추원 개편을 통해 의회 설립을 추진하였다.","군사 조직으로 한인 국방 경위대를 창설하였다.","순종의 인산일을 기회로 만세 운동을 계획하였다.","광주 학생 항일 운동에 진상 조사단을 파견하였다."],"a":5,"e":"민족 단일당·지회·해소는 신간회(1927~1931)이다. 신간회는 광주 학생 항일 운동에 진상 조사단을 파견하였다. ①천도교 ②독립협회 ④6·10 만세 운동.","sec":8},{"id":"kh-g77-39","set":"제77회 기출","n":39,"s":1,"q":"[자료] [교사 질문] 대공황 이후 일제가 공업 원료 확보를 위해 한반도 남부에 면화 재배를 확대한 정책. (자료: 강압적 면화 재배로 경주 농민 수백 명 궐기, 경북 농가 민심 악화 기사)\n\n이 정책이 시행된 시기에 있었던 사실로 옳은 것은?","o":["조선 민립 대학 기성회가 조직되었다.","메가타의 주도로 화폐 정리 사업이 시행되었다.","귀속 재산 관리를 위해 신한 공사가 운영되었다.","회사 설립을 허가제로 하는 회사령이 공포되었다.","농민의 자력갱생을 내세운 농촌 진흥 운동이 추진되었다."],"a":5,"e":"대공황 이후 남면북양 정책은 1930년대이다. 이 시기 일제는 농촌 진흥 운동을 추진하였다. ①1923 ②1905 ③광복 후 ④1910.","sec":8},{"id":"kh-g77-40","set":"제77회 기출","n":40,"s":1,"q":"[자료] [공연: 대중가요의 역사를 찾아서] 이애리수 '황성옛터'(만월대의 텅 빈 밤) / (가) - 비극적인 삶으로 빚어낸 염세와 허무 / 고복수 '타향살이' / 이난영 '목포의 눈물'.\n\n(가)에 들어갈 내용으로 옳은 것은?","o":["김민기, 아침 이슬","윤심덕, 사의 찬미","현인, 굳세어라 금순아","코리아나, 손에 손 잡고","이해연, 단장의 미아리 고개"],"a":2,"e":"'비극적 삶·염세·허무'는 일제 강점기 윤심덕의 '사의 찬미'이다. ①1970년대 ③6·25 후 ④1988 서울올림픽 ⑤6·25 후.","sec":8},{"id":"kh-g77-41","set":"제77회 기출","n":41,"s":1,"q":"[자료] 국민부의 항일 행동이 검거로 꺾이자 양세봉·양하산 등이 흩어진 단원을 모아 국민부 산하 무장 단체를 재편함. 총사령관 양세봉의 지휘 아래 이 부대는 한중 연합군을 편성하여 소양구에 이어 영릉가를 점령하였다.\n\n밑줄 그은 '이 부대'에 대한 설명으로 옳은 것은?","o":["흥경성 전투에서 일본군을 격퇴하였다.","일본군의 공세를 피해 자유시로 이동하였다.","이른바 남한 대토벌 작전으로 큰 피해를 입었다.","영국군의 요청으로 인도·미얀마 전선에 파견되었다.","한국인 유격대를 중심으로 조국 광복회를 조직하였다."],"a":1,"e":"양세봉·영릉가 전투는 조선 혁명군이다. 조선 혁명군은 흥경성 전투에서도 일본군을 격퇴하였다. ②대한독립군단 ③의병 ④한국광복군 ⑤동북항일연군.","sec":8},{"id":"kh-g77-42","set":"제77회 기출","n":42,"s":1,"q":"[자료] [어느 독립운동가의 주요 행적(시간 순)] 1 상하이: 대동단결 선언 작성 참여 / 2 항저우: 윤봉길 의거 이후 일제 탄압 피해 머무름 / 3 난징: (가) / 4 충칭: 삼균주의에 바탕을 둔 임시 정부 건국 강령 초안 작성.\n\n(가)에 들어갈 내용으로 옳은 것은?","o":["흥사단을 창립함.","이토 히로부미를 사살함.","한국독립운동지혈사를 저술함.","한국 독립군의 총사령관으로 활약함.","김원봉 등과 함께 민족 혁명당을 결성함."],"a":5,"e":"대동단결 선언·삼균주의·임정 건국 강령은 조소앙이다. 조소앙은 난징에서 김원봉 등과 민족 혁명당(1935)을 결성하였다. ①안창호 ②안중근 ③박은식 ④지청천.","sec":8},{"id":"kh-g77-43","set":"제77회 기출","n":43,"s":1,"q":"[자료] [한국사 교양 강좌: 기념일에 담긴 일제 강점기 사회·문화] 제1강 어린이날 / 제2강 메이데이(첫 노동절) / 제3강 과학 데이 / 제4강 (가).\n\n(가)에 들어갈 내용으로 가장 적절한 것은?","o":["제헌절 - 첫 헌법 제정의 의미를 강조하다","가갸날 - 우리 말과 글의 소중함을 되새기다","향토 예비군의 날 - 범국민적 안보의식을 조성하다","은사의 날 - 스승을 향한 감사의 마음을 전하다","이산가족의 날 - 이산가족 문제에 대한 관심을 제고하다"],"a":2,"e":"일제 강점기에 기린 기념일이어야 한다. 조선어연구회가 훈민정음 반포를 기려 만든 '가갸날'(1926)이 이에 해당한다. ①①③④⑤는 광복 이후.","sec":8},{"id":"kh-g77-44","set":"제77회 기출","n":44,"s":1,"q":"[자료] 이곳은 인천 부평의 일본 육군 조병창이다. 일제가 국가 총동원법을 시행한 시기에 전쟁 무기 생산을 목적으로 설치되었으며, 학도 동원 실시 요강에 따라 학생들이 강제로 동원되기도 하였다.\n\n밑줄 그은 '시기'에 볼 수 있는 모습으로 가장 적절한 것은?","o":["원산 총파업에 동참하는 노동자","국채 보상 운동에 성금을 내는 상인","원각사에서 연극 은세계를 공연하는 배우","황국 신민 서사를 암송하는 국민학교 학생","조선 형평사 창립 대회 현장을 취재하는 기자"],"a":4,"e":"국가 총동원법(1938)은 민족 말살 통치기이다. 이 시기에는 황국 신민 서사를 암송하는 국민학교 학생을 볼 수 있었다. ①1929 ②1907 ③1908 ⑤1923.","sec":8},{"id":"kh-g77-45","set":"제77회 기출","n":45,"s":1,"q":"[자료] 농민은 평년 수확의 절반가량을 상환금 등으로 납부해 식량도 확보 못 할 지경이라 상환 연기·분배 취소를 호소함. 지주는 정조 1석당 헐값으로 환산된 지가 증권을 액면가 이하로 매각하는 등 어려움을 겪음.\n\n다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","o":["농지 개혁의 전개 과정을 알아본다.","광주 대단지 사건의 결과를 파악한다.","개발 제한 구역 설정의 목적을 찾아본다.","산미 증식 계획의 추진 배경을 분석한다.","지계아문이 추진한 정책의 내용을 조사한다."],"a":1,"e":"지가 증권·상환·분배는 제헌 국회가 실시한 농지 개혁(1950)이다. ②1971 ③1970년대 ④일제 ⑤대한제국.","sec":9},{"id":"kh-g77-46","set":"제77회 기출","n":46,"s":1,"q":"[자료] 미소 공동 위원회 미국 대표단 정치고문 버치 중위가 좌우 합작을 주도한 (가)을/를 추모하며 남긴 연설문. 엔도 정무총감과의 회담에서 요구 사항을 관철하는 등 해방 정국을 주도하던 (가)이/가 암살됨.\n\n(가) 인물에 대한 설명으로 옳은 것은?","o":["광복에 대비하여 조선 건국 동맹을 결성하였다.","대한민국 임시 정부 초대 국무총리를 역임하였다.","정읍에서 남한만의 단독 정부 수립을 주장하였다.","헤이그에서 열린 만국 평화 회의에 특사로 파견되었다.","민족을 역사 서술의 중심에 둔 독사신론을 발표하였다."],"a":1,"e":"엔도 회담·좌우 합작 주도·암살은 여운형이다. 여운형은 광복에 대비해 조선 건국 동맹을 결성하였다. ②이동휘 ③이승만 ④이준 등 ⑤신채호.","sec":9},{"id":"kh-g77-47","set":"제77회 기출","n":47,"s":1,"q":"[자료] 이것은 (가) 정부가 작성한 행정 수도 건설 계획의 일부이다. 수출 100억 달러를 처음 달성한 (가) 정부는 수도권 인구 과밀 억제를 내세우며 충남 공주시 장기면 등을 대상으로 행정 수도 건설 계획을 발표하였다.\n\n(가) 정부 시기에 있었던 사실로 옳은 것은?","o":["최저 임금 위원회가 설치되었다.","포항 제철소 1기 설비가 준공되었다.","전국 민주 노동조합 총연맹이 창립되었다.","칠레와의 자유 무역 협정(FTA)이 체결되었다.","경제 협력 개발 기구(OECD) 회원국이 되었다."],"a":2,"e":"수출 100억 달러 달성(1977)·행정 수도 계획은 박정희 정부이다. 이 시기 포항 제철소 1기 설비가 준공(1973)되었다. ①1980년대 후반 ③1995 ④2004 ⑤1996.","sec":9},{"id":"kh-g77-48","set":"제77회 기출","n":48,"s":1,"q":"[자료] [대화] 김영삼 신민당 총재가 국회의원 최초로 제명된 사건. 김영삼이 뉴욕 타임스 인터뷰, 그리고 신민당사에서 농성하던 YH 무역 노동자를 강제 진압한 정부를 비판한 것이 이유였다.\n\n다음 대화에 나타난 사건 이후에 전개된 사실로 옳은 것은?","o":["애치슨 라인이 발표되었다.","부마 민주 항쟁이 일어났다.","사사오입의 논리로 개헌안이 통과되었다.","반민족 행위 특별 조사 위원회가 해체되었다.","민의원, 참의원으로 구성된 양원제 국회가 탄생하였다."],"a":2,"e":"YH 무역 사건·김영삼 제명(1979.10)은 유신 말기이다. 직후 부마 민주 항쟁이 일어났다. ①1950 ③1954 ④1949 ⑤1960.","sec":9},{"id":"kh-g77-49","set":"제77회 기출","n":49,"s":1,"q":"[자료] [보도 지침] '대학생들 주한 미상공회의소 점거' 기사는 사회면 톱·사진 쓰지 말 것. 기사 제목에 '호헌', '개헌'이란 말은 일체 쓰지 말 것. NCC 고문대책위 구성 보도하지 말 것. (이 정부의 언론 통제)\n\n밑줄 그은 '이 정부' 시기에 있었던 사실로 옳은 것은?","o":["헝가리에 상주 대표부가 설치되었다.","박종철 고문 치사 사건이 발생하였다.","평화 통일을 주장한 조봉암이 처형되었다.","대통령 긴급 명령으로 금융 실명제가 실시되었다.","서울역에서 청량리역 간에 서울 지하철 1호선이 개통되었다."],"a":2,"e":"보도 지침·호헌은 전두환 정부이다. 이 시기 박종철 고문 치사 사건(1987)이 발생해 6월 민주 항쟁으로 이어졌다. ①노태우 정부 ③이승만 정부 ④김영삼 정부 ⑤박정희 정부(1974).","sec":9},{"id":"kh-g77-50","set":"제77회 기출","n":50,"s":1,"q":"[자료] [천도] 고구려는 427년 (가)이/가 평양 천도. 백제는 475년 한성 함락 후 (나)이/가 웅진 천도, 538년 (다)은/는 사비 천도. 고려는 1232년 최우 건의로 (라)이/가 강화도 천도. 조선은 1394년 (마)이/가 한양 천도.\n\n(가)~(마)에 해당하는 왕에 대한 설명으로 옳은 것은?","o":["(가) - 서안평을 공격하여 영토를 확대하였다.","(나) - 소지 마립간과 혼인 동맹을 맺었다.","(다) - 국호를 남부여라 칭하였다.","(라) - 쌍성총관부를 수복하였다.","(마) - 경국대전을 완성하였다."],"a":3,"e":"(가)장수왕 (나)문주왕 (다)성왕 (라)고종 (마)태조 이성계. 성왕은 국호를 남부여로 고쳤다. ①미천왕 ②동성왕 ④공민왕 ⑤성종.","sec":2}];
